using System;
using System.Diagnostics;
using System.Globalization;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis.CSharp.Scripting.Hosting;
using Xunit;

namespace StressTests
{
    public class StressTests
    {
        [Fact]
        public async Task TestKill()
        {
            var options = new InteractiveHostOptions();
            using var host = new InteractiveHost(options);

            for (int i = 0; i < 10; i++)
            {
                await TestKillAfterAsync(host, TimeSpan.FromMilliseconds(100 * i));
            }
        }

        private async Task TestKillAfterAsync(InteractiveHost host, TimeSpan delay)
        {
            try
            {
                var task = Task.Run(async () =>
                {
                    await Task.Delay(delay);
                    try
                    {
                        Process.GetCurrentProcess().Kill();
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Failed to kill process: {ex.Message}");
                    }
                });

                for (int i = 0; i < 100; i++)
                {
                    await host.ExecuteAsync("1 + 1");
                }

                await task;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Test failed: {ex.Message}");
            }
        }
    }
}

using System;
using System.IO;
using System.Linq;

public class ClusterDataManager
{
    private StructureBspClusterBlock clusterBlock;
    private GeometryBlockInfo geometryBlockInfo;
    private ClusterData clusterData;

    public ClusterDataManager(StructureBspClusterBlock clusterBlock, GeometryBlockInfo geometryBlockInfo)
    {
        this.clusterBlock = clusterBlock;
        this.geometryBlockInfo = geometryBlockInfo;
    }

    public IntPtr GetResourcePointer()
    {
        return clusterBlock.ResourcePointer;
    }

    public int GetResourceLength()
    {
        return clusterBlock.ResourceLength;
    }

    public void SetResourcePointer(IntPtr pointer)
    {
        clusterBlock.ResourcePointer = pointer;
    }

    public void SetResourceLength(int length)
    {
        clusterBlock.ResourceLength = length;
    }

    public bool IsClusterDataLoaded()
    {
        return clusterData != null;
    }

    public void LoadClusterData(Stream stream)
    {
        if (stream == null || stream.Length == 0)
        {
            throw new ArgumentException("Invalid stream");
        }

        using (var reader = new BinaryReader(stream))
        {
            var dataBlock = new StructureBspClusterDataBlockNew();
            dataBlock.Deserialize(reader);

            clusterData = new ClusterData(dataBlock);
        }
    }

    public void DeleteClusterData()
    {
        if (clusterData != null)
        {
            clusterData.Dispose();
            clusterData = null;
        }
    }
}

