using System;

class DiamondTrolls
{
    static void Main()
    {
        Console.Write("Enter the size of the diamond: ");
        int n = Convert.ToInt32(Console.ReadLine());

        int width = 2 * n + 1;
        int height = 2 * n + 1;

        // Print top half of the diamond
        for (int i = 0; i < n; i++)
        {
            int topDots = n - i;
            int asterisks = 2 * i + 1;

            Console.Write(new string(' ', topDots));
            Console.Write(new string('*', asterisks));
            Console.Write(new string(' ', topDots));
            Console.WriteLine();
        }

        // Print middle line of asterisks
        Console.Write(new string('*', width));
        Console.WriteLine();

        // Print bottom half of the diamond
        for (int i = n - 1; i >= 0; i--)
        {
            int bottomDots = n - i;
            int asterisks = 2 * i + 1;

            Console.Write(new string(' ', bottomDots));
            Console.Write(new string('*', asterisks));
            Console.Write(new string(' ', bottomDots));
            Console.WriteLine();
        }
    }
}

using Newtonsoft.Json.Linq;
using Skybrud.Essentials.Json.Extensions;
