namespace Skybrud.Social.Slack.Models.Conversations {

    /// <summary>
    /// Class representing the topic a Slack conversation.
    /// </summary>
    public class SlackConversationTopic : SlackObject {

        /// <summary>
        /// Gets the value representing the topic.
        /// </summary>
        public string Value { get; }

        /// <summary>
        /// Gets the user who set the topic.
        /// </summary>
        public string Creator { get; }

        /// <summary>
        /// Gets a timestamp for when the topic was last updated.
        /// </summary>
        public EssentialsTime LastSet { get; }

        /// <summary>
        /// Initializes a new instance based on the specified <paramref name="json"/> object.
        /// </summary>
        /// <param name="json">An instance of <see cref="JObject"/> representing the jsonect.</param>
        protected SlackConversationTopic(JObject json) : base(json) {
            Value = json.GetString("value");
            Creator = json.GetString("creator");
            LastSet = json.GetInt64("last_set", ParseUnixTimestamp);
        }

        /// <summary>
        /// Parses the specified <paramref name="json"/> object into an instance of <see cref="SlackConversationTopic"/>.
        /// </summary>
        /// <param name="json">The instance of <see cref="JObject"/> to parse.</param>
        /// <returns>An instance of <see cref="SlackConversationTopic"/>.</returns>
        public static SlackConversationTopic Parse(JObject json) {
            return json == null ? null : new SlackConversationTopic(json);
        }

    }

}

using System;
using System.Threading.Tasks;
using Akka.Actor;
using Akka.Dispatch;
using Akka.Dispatch.MessageQueues;

public static class InternalExtensions
{
    public static void NotifyAboutReplayCompletion(this Task task, IActorRef actor)
    {
        task.ContinueWith(t =>
        {
            if (t.IsCompletedSuccessfully)
            {
                actor.Tell(new SuccessNotification());
            }
            else if (t.IsFaulted)
            {
                actor.Tell(new FailureNotification(t.Exception));
            }
            else if (t.IsCanceled)
            {
                actor.Tell(new CanceledNotification());
            }
        });
    }

    public static void EnqueueMessageFirst(this IActorContext context, object message)
    {
        var cell = context as ActorCell;
        if (cell != null)
        {
            var mailbox = cell.Mailbox;
            if (mailbox.Queue is UnboundedDequeMessageQueue queue)
            {
                queue.EnqueueFirst(new Envelope(message, null));
            }
        }
    }
}

public class SuccessNotification { }

public class FailureNotification
{
    public Exception Exception { get; }

    public FailureNotification(Exception exception)
    {
        Exception = exception;
    }
}

public class CanceledNotification { }

