using System.Threading.Tasks;
using Microsoft.CodeAnalysis.Editor.Options;
using Microsoft.CodeAnalysis.Options;
using Microsoft.VisualStudio.Extensibility.Testing;

public class StateResetInProcess
{
    public static async Task ResetAsync()
    {
        // Get the global option service to modify global settings.
        var globalOptionsService = await TestServices.Shell.GetComponentModelServiceAsync<IGlobalOptionService>();

        // Get the editor options factory service to modify editor settings.
        var editorOptionsFactoryService = await TestServices.Shell.GetComponentModelServiceAsync<IEditorOptionsFactoryService>();
        var editorOptions = editorOptionsFactoryService.GlobalOptions;

        // Reset global code analysis options: Enable navigation bar for C#.
        await globalOptionsService.SetGlobalOptionAsync(
            new OptionKey(NavigationBarViewOptions.NavigationBarEnabledFeatureFlag, LanguageNames.CSharp), true);

        // Reset host-level editor settings: Disable suggestion mode for general editor.
        await editorOptions.SetUseSuggestionModeAsync(
            new EditorOptionKey<bool>(DefaultOptions.UseSuggestionModeOptionKey), false);

        // Reset host-level editor settings: Enable suggestion mode for debugger editor.
        await editorOptions.SetUseSuggestionModeAsync(
            new EditorOptionKey<bool>(DefaultOptions.DebuggerTextViewUseSuggestionModeOptionKey), true);

        // Reset host-level editor settings: Disable responsive code completion.
        editorOptions.SetOptionValue(DefaultOptions.ResponsiveCodeCompletionOptionId, false);

        // Reset host-level editor settings: Disable typing latency guard.
        editorOptions.SetOptionValue(DefaultOptions.TypingLatencyGuardOptionId, false);
    }
}

