    /// <summary>
    /// Exposes methods that the Shell uses to retrieve flags and info tip information
    /// for an item that resides in an IShellFolder implementation. Info tips are usually
    /// displayed inside a tooltip control.
    /// </summary>
    [ComImport]
    [Guid("00021500-0000-0000-C000-000000000046")]
    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    public interface IQueryInfo
    {
        /// <summary>
        /// Gets the info tip text for an item.
        /// </summary>
        /// <param name="dwFlags">Flags that direct the handling of the item from which you're retrieving the info tip text. This value is commonly zero.</param>
        /// <param name="ppwszTip">he address of a Unicode string pointer that, when this method returns successfully, receives the tip string pointer. Applications that implement this method must allocate memory for ppwszTip by calling CoTaskMemAlloc.
        /// Calling applications must call CoTaskMemFree to free the memory when it is no longer needed.</param>
        /// <returns>Returns S_OK if the function succeeds. If no info tip text is available, ppwszTip is set to NULL. Otherwise, returns a COM-defined error value.</returns>
        [PreserveSig]
        int GetInfoTip(QITIPF dwFlags, [MarshalAs(UnmanagedType.LPWStr)] out string ppwszTip);

        /// <summary>
        /// Gets the information flags for an item. This method is not currently used.
        /// </summary>
        /// <param name="pdwFlags">A pointer to a value that receives the flags for the item. If no flags are to be returned, this value should be set to zero.</param>
        /// <returns>Returns S_OK if pdwFlags returns any flag values, or a COM-defined error value otherwise.</returns>
        [PreserveSig]
        int GetInfoFlags(out int pdwFlags);
    }
}

using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Windows.Forms;
using System.Diagnostics;
using System.IO;
using Kitware.VTK;

public class Form1 : Form
{
    private vtkDEMReader demReader;
    private vtkLookupTable colorLookupTable;
    private vtkImageMapToColors mapToColors;
    private vtkImageActor imageActor;
    private vtkRenderWindow renderWindow;
    private vtkRenderer renderer;

    public Form1()
    {
        // Initialize VTK environment
        vtkObject.GlobalWarningDisplayOff();

        // Create a new instance of vtkDEMReader
        demReader = vtkDEMReader.New();

        // Set the file name of the DEM file
        string filePath = Environment.GetEnvironmentVariable("VTK_DATA_ROOT") + "\\\\SainteHelens.dem";
        demReader.SetFileName(filePath);

        // Create a lookup table for color mapping
        colorLookupTable = vtkLookupTable.New();
        colorLookupTable.SetHueRange(0.667, 0);
        colorLookupTable.SetSaturationRange(1, 1);
        colorLookupTable.SetValueRange(1, 1);

        // Create an image map to colors
        mapToColors = vtkImageMapToColors.New();
        mapToColors.SetInputConnection(demReader.GetOutputPort());
        mapToColors.SetLookupTable(colorLookupTable);

        // Create an image actor
        imageActor = vtkImageActor.New();
        imageActor.GetMapper().SetInputConnection(mapToColors.GetOutputPort());

        // Create a renderer
        renderer = vtkRenderer.New();

        // Add the actor to the renderer
        renderer.AddActor(imageActor);

        // Create a render window
        renderWindow = vtkRenderWindow.New();
        renderWindow.AddRenderer(renderer);

        // Set up the render window control
        vtkWin32RenderWindowInteractor renderWindowInteractor = vtkWin32RenderWindowInteractor.New();
        renderWindowInteractor.SetRenderWindow(renderWindow);
    }

    private void renderWindowControl1_Load(object sender, EventArgs e)
    {
        // Render the image
        renderWindow.Render();
    }

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.Run(new Form1());
    }
}

using System;
using System.Reflection;

namespace Light.DataCore
{
    abstract class DynamicFieldMapping : FieldMapping
    {
        public static DynamicFieldMapping CreateDynmaicFieldMapping (PropertyInfo property, DynamicCustomMapping mapping)
        {
            DynamicFieldMapping fieldMapping;
            Type type = property.PropertyType;
            TypeInfo typeInfo = type.GetTypeInfo();
            string fieldName = property.Name;
            if (typeInfo.IsGenericType) {
                Type frameType = type.GetGenericTypeDefinition ();
                if (frameType.FullName == "System.Nullable`1") {
                    Type [] arguments = type.GetGenericArguments ();
                    type = arguments [0];
                    typeInfo = type.GetTypeInfo();
                }
            }

            if (type.IsArray) {
                throw new LightDataException(string.Format(SR.DataMappingUnsupportFieldType, property.DeclaringType, property.Name, type));
            }
            else if (type.IsGenericParameter || typeInfo.IsGenericTypeDefinition) {
                throw new LightDataException(string.Format(SR.DataMappingUnsupportFieldType, property.DeclaringType, property.Name, type));
            }
            else if (typeInfo.IsEnum) {
                DynamicEnumFieldMapping enumFieldMapping = new DynamicEnumFieldMapping (type, fieldName, mapping);
                fieldMapping = enumFieldMapping;
            }
            else {
                TypeCode code = Type.GetTypeCode (type);
                switch (code) {
                case TypeCode.Empty:
                case TypeCode.Object:
                    throw new LightDataException(string.Format(SR.DataMappingUnsupportFieldType, property.DeclaringType, property.Name, type));
                default:
                    DynamicPrimitiveFieldMapping primitiveFieldMapping = new DynamicPrimitiveFieldMapping (type, fieldName, mapping);
                    fieldMapping = primitiveFieldMapping;
                    break;
                }
            }
            return fieldMapping;
        }

        protected DynamicFieldMapping (Type type, string fieldName, DynamicCustomMapping mapping, bool isNullable)
            : base (type, fieldName, fieldName, mapping, isNullable, null)
        {

        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using EPiServer;
using EPiServer.Core;
using EPiServer.DataAbstraction;
using EPiServer.ServiceLocation;

public static class CategorizableExtensions
{
    /// <summary>
    /// Gets theme CSS class names based on content categories.
    /// </summary>
    /// <param name="content">The categorizable content.</param>
    /// <returns>An array of unique CSS class names, or an empty array if no categories or matches are found.</returns>
    public static string[] GetThemeCssClassNames(this ICategorizable content)
    {
        if (content == null || content.Category == null || !content.Category.Any())
        {
            return Array.Empty<string>();
        }

        var categoryRepository = ServiceLocator.Current.GetInstance<ICategoryRepository>();
        var cssClasses = new HashSet<string>();

        foreach (var categoryId in content.Category)
        {
            var category = categoryRepository.Get(categoryId);
            if (category != null)
            {
                switch (category.Name)
                {
                    case "Meet":
                        cssClasses.Add("theme1");
                        break;
                    case "Track":
                        cssClasses.Add("theme2");
                        break;
                    case "Plan":
                        cssClasses.Add("theme3");
                        break;
                        // Add more category to theme mappings as needed
                }
            }
        }

        return cssClasses.ToArray();
    }
}

using UnityEngine;
using System.Collections;

public class EndScreenController : ScreenController {

    public UnityEngine.UI.Text winnerText;
    public UnityEngine.UI.Text player1Text;
    public UnityEngine.UI.Text player2Text;

    public UnityEngine.UI.Text nextLeftPlayers;
    public UnityEngine.UI.Text nextRightPlayers;

    protected override void OnActivation() {
        gameObject.SetActive(true);

        winnerText.text = "...";
        player1Text.text = "...";
        player2Text.text = "...";

        nextLeftPlayers.text = "...";
        nextRightPlayers.text = "...";

        int matchId = eventInfo.matchId;
        StartCoroutine (DownloadMatchInfo (matchId));
    }

    protected override void OnDeactivation() {
    }

    protected override void OnMatchInfoDownloaded (MatchInfo matchInfo) {
        if (matchInfo.state != "OK") {
            int matchId = eventInfo.matchId;
            StartCoroutine (DownloadMatchInfo (matchId));
            return;
        }

        Bot winner = matchInfo.GetWinner();

        if (winner == null) {
            winnerText.text = "Draw!";

            Bot[] bots = matchInfo.bots;

            player1Text.text = createText (bots[0].name, -1);
            player2Text.text = createText (bots[1].name, -1);
        } else {
            winnerText.text = winner.name + " wins!";

            Bot looser = matchInfo.GetLooser ();

            player1Text.text = createText (winner.name, 3);
            player2Text.text = createText (looser.name, 0);
        }

        int tournamentId = matchInfo.tournamentId;
        StartCoroutine(DownloadUpcomingMatches(tournamentId));
    }

    protected override void OnUpcomingMatchesDownloaded(UpcomingMatches upcomingMatches) {
        Match[] matches = upcomingMatches.matches;

        nextLeftPlayers.text = "";
        nextRightPlayers.text = "";

        for (int i = 0; i < 3 && i < matches.Length; i++) {
            Match match = matches [i];
            string botNameLeft = match.bots [0];
            string botNameRight = match.bots [1];

            if (i > 0) {
                nextLeftPlayers.text += "\n";
                nextRightPlayers.text += "\n";
            }
            nextLeftPlayers.text += botNameLeft;
            nextRightPlayers.text += botNameRight;
        }
    }

    private string createText(string botName, int pts) {
        string sign = pts >= 0 ? "+" : "";
        return botName + "\n" + sign + pts + " pts";
    }

}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace shiwch.util
{
    /// <summary>
    /// 字节数组相等比较器
    /// </summary>
    public sealed class ByteArrayEqualityComparer : IEqualityComparer<byte[]>
    {
        /// <summary>
        /// 判断两个字节数组是否相等
        /// </summary>
        /// <param name="first"></param>
        /// <param name="second"></param>
        /// <returns></returns>
        public bool Equals(byte[] first, byte[] second)
        {
            return ByteEquals(first, second);
        }

        /// <summary>
        /// 判断两个字节数组是否相等
        /// </summary>
        /// <param name="first"></param>
        /// <param name="second"></param>
        /// <returns></returns>
        public static bool ByteEquals(byte[] first, byte[] second)
        {
            if (first == second)
            {
                return true;
            }
            if (first == null || second == null)
            {
                return false;
            }
            if (first.Length != second.Length)
            {
                return false;
            }
            for (int i = 0; i < first.Length; i++)
            {
                if (first[i] != second[i])
                {
                    return false;
                }
            }
            return true;
        }

        public int GetHashCode(byte[] array)
        {
            if (array == null)
            {
                return 0;
            }
            int num = 17;
            for (int i = 0; i < array.Length; i++)
            {
                byte b = array[i];
                num = num * 31 + (int)b;
            }
            return num;
        }
    }
}

using BenchmarkDotNet.Attributes;

namespace FuncSharp.Benchmarks
{
    [MemoryDiagnoser]
    public class OptionBenchmarks
    {
        private object Object { get; } = new object();
        private IOption<string> NonEmptyOption { get; } = "non-empty".ToOption();
        private IOption<string> EmptyOption { get; } = Option.Empty<string>();

        [Benchmark]
        public void Creation()
        {
            Option.Create(42);
            Option.Create(42 as int?);
            Option.Create(null as int?);

            Option.Create(Object);
            Option.Create(null as object);
        }

        [Benchmark]
        public void Retrieval()
        {
            var a = NonEmptyOption.NonEmpty;
            var b = EmptyOption.NonEmpty;
            var c = NonEmptyOption.IsEmpty;
            var d = EmptyOption.IsEmpty;

            NonEmptyOption.Get();

            NonEmptyOption.GetOrElse("else");
            EmptyOption.GetOrElse("else");

            NonEmptyOption.OrElse(_ => NonEmptyOption);
            EmptyOption.OrElse(_ => NonEmptyOption);
        }

        [Benchmark]
        public void Mapping()
        {
            NonEmptyOption.Map(o => "non-empty-mapped");
            EmptyOption.Map(o => "empty-mapped");

            NonEmptyOption.FlatMap(o => EmptyOption);
            NonEmptyOption.FlatMap(o => NonEmptyOption);
            EmptyOption.FlatMap(o => EmptyOption);
            EmptyOption.FlatMap(o => NonEmptyOption);
        }

        [Benchmark]
        public void Matching()
        {
            NonEmptyOption.Match(_ => true, _ => false);
            EmptyOption.Match(_ => true, _ => false);
        }

        [Benchmark]
        public void ToEnumerable()
        {
            NonEmptyOption.ToEnumerable();
            EmptyOption.ToEnumerable();
        }
    }
}

