using System;
using System.Collections.ObjectModel;

public class PESection
{
    public string Name { get; set; }
    public PEFile Owner { get; internal set; }

    public PESection(string name)
    {
        Name = name;
    }
}

public class PEFile
{
    public string FilePath { get; set; }
    public PESectionCollection Sections { get; }

    public PEFile(string filePath)
    {
        FilePath = filePath;
        Sections = new PESectionCollection(this);
    }
}

public class PESectionCollection : Collection<PESection>
{
    private readonly PEFile _owner;

    public PESectionCollection(PEFile owner)
    {
        _owner = owner;
    }

    private void AssertHasNoOwner(PESection section)
    {
        if (section == null)
            throw new ArgumentNullException(nameof(section));
        if (section.Owner != null)
            throw new InvalidOperationException($"Section '{section.Name}' already belongs to another PE file.");
    }

    protected override void ClearItems()
    {
        foreach (var section in Items)
            section.Owner = null;
        base.ClearItems();
    }

    protected override void InsertItem(int index, PESection item)
    {
        AssertHasNoOwner(item);
        base.InsertItem(index, item);
        item.Owner = _owner;
    }

    protected override void SetItem(int index, PESection item)
    {
        AssertHasNoOwner(item);
        if (index >= 0 && index < Count)
            this[index].Owner = null;
        base.SetItem(index, item);
        item.Owner = _owner;
    }

    protected override void RemoveItem(int index)
    {
        if (index >= 0 && index < Count)
            this[index].Owner = null;
        base.RemoveItem(index);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace DataGenerator.Sources
{
    /// <summary>
    /// A base class for data source property types
    /// </summary>
    /// <seealso cref="DataGenerator.Sources.DataSourceBase" />
    public abstract class DataSourcePropertyType : DataSourceBase
    {
        /// <summary>
        /// Initializes a new instance of the <see cref="DataSourcePropertyType"/> class.
        /// </summary>
        /// <param name="types">The types.</param>
        protected DataSourcePropertyType(IEnumerable<Type> types)
            : this(DataSourceBase.PropertyTypePriority, types)
        {
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="DataSourcePropertyType"/> class.
        /// </summary>
        /// <param name="priority">The priority.</param>
        /// <param name="types">The types.</param>
        /// <exception cref="System.ArgumentNullException"></exception>
        protected DataSourcePropertyType(int priority, IEnumerable<Type> types)
            : base(priority)
        {
            if (types == null)
                throw new ArgumentNullException(nameof(types));

            Types = types;
        }

        /// <summary>
        /// Gets the types this data source will generate values for.
        /// </summary>
        /// <value>
        /// The types this data source will generate values for.
        /// </value>
        public IEnumerable<Type> Types { get; }

        /// <summary>
        /// Test if the current <paramref name="mappingContext" /> can use this data source.
        /// </summary>
        /// <param name="mappingContext">The mapping context.</param>
        /// <returns>
        ///   <c>true</c> if this data source can be used; otherwise <c>false</c>.
        /// </returns>
        public override bool TryMap(IMappingContext mappingContext)
        {
            var memberType = mappingContext?.MemberMapping?.MemberAccessor?.MemberType;
            return Types.Any(t => t == memberType);
        }
    }
}

