using Microsoft.Owin.Security.OAuth;
using System.Security.Claims;
using System.Threading.Tasks;
using System;

public class OAuthProvider : OAuthAuthorizationServerProvider
{
    private readonly IIdentityService _identityService;

    public OAuthProvider(IIdentityService identityService)
    {
        _identityService = identityService ?? throw new ArgumentNullException(nameof(identityService));
    }

    public override async Task GrantResourceOwnerCredentials(OAuthGrantResourceOwnerCredentialsContext context)
    {
        var username = context.UserName;
        var password = context.Password;

        try
        {
            var userIdentity = await _identityService.AuthenticateUserAsync(username, password);
            if (userIdentity != null)
            {
                var identity = new ClaimsIdentity("chloe");
                identity.AddClaim(new Claim(ClaimTypes.Name, username));

                var claims = await _identityService.GetUserClaimsAsync(userIdentity.UserId);
                if (claims != null)
                {
                    foreach (var claim in claims)
                    {
                        identity.AddClaim(claim);
                    }
                }
                context.Validated(identity);
                return;
            }
            context.SetError("invalid_grant", "Invalid username or password.");
            return;
        }
        catch (Exception)
        {
            context.SetError("server_error", "An unexpected error occurred.");
            return;
        }
    }

    public override async Task ValidateClientAuthentication(OAuthValidateClientAuthenticationContext context)
    {
        context.Validated();
    }
}

using System;
using System.Runtime.InteropServices;

public class Finder
{
    [STAThread]
    public static void Main(string[] args)
    {
        object application = null;
        try
        {
            application = Marshal.GetActiveObject("SolidEdge.Application");
        }
        catch (COMException)
        {
            Console.WriteLine("Solid Edge is not running. Please start Solid Edge.");
            return;
        }

        dynamic app = application;
        dynamic documents = app.Documents;
        dynamic partDocument = documents.Add("PartDocument.PartDocument");
        dynamic refPlanes = partDocument.RefPlanes;
        dynamic profileSets = partDocument.ProfileSets;
        dynamic profileSet = profileSets.Add();
        dynamic profiles = profileSet.Profiles;
        dynamic profile = profiles.Add(refPlanes.Item(3)); // Base reference plane
        dynamic circles2d = profile.Circles2d;

        double centerX = 0.1;
        double centerY = 0.1;
        double radius = 0.05;

        dynamic circle2d = circles2d.AddByCenterRadius(centerX, centerY, radius);

        double x = circle2d.CenterPoint.X;
        double y = circle2d.CenterPoint.Y;

        Console.WriteLine($"Circle created at ({x}, {y}) with radius {radius}.");
    }
}

/*============================================================
**
** Interface:  IDictionary
**
**
**
**
** Purpose: Base interface for all dictionaries.
**
**
===========================================================*/

using System;
using System.Diagnostics.Contracts;

namespace System.Collections
{
    // An IDictionary is a possibly unordered set of key-value pairs.
    // Keys can be any non-null object.  Values can be any object.
    // You can look up a value in an IDictionary via the default indexed
    // property, Items.
    public interface IDictionary : ICollection
    {
        // Interfaces are not serializable
        // The Item property provides methods to read and edit entries
        // in the Dictionary.
        Object this[Object key]
        {
            get;
            set;
        }

        // Returns a collections of the keys in this dictionary.
        ICollection Keys
        {
            get;
        }

        // Returns a collections of the values in this dictionary.
        ICollection Values
        {
            get;
        }

        // Returns whether this dictionary contains a particular key.
        //
        bool Contains(Object key);

        // Adds a key-value pair to the dictionary.
        //
        void Add(Object key, Object value);

        // Removes all pairs from the dictionary.
        void Clear();

        bool IsReadOnly
        { get; }

        bool IsFixedSize
        { get; }

        // Returns an IDictionaryEnumerator for this dictionary.
        new IDictionaryEnumerator GetEnumerator();

        // Removes a particular key from the dictionary.
        //
        void Remove(Object key);
    }
}

using System;

namespace NCDK.FaulonSignatures
{
    public class InvariantIntStringPair : IComparable<InvariantIntStringPair>
    {
        private readonly string stringValue;
        private readonly int value;
        private readonly int originalIndex;

        public InvariantIntStringPair(string stringValue, int value, int originalIndex)
        {
            this.stringValue = stringValue;
            this.value = value;
            this.originalIndex = originalIndex;
        }

        public bool Equals(string stringValue, int value)
        {
            return this.value == value && string.Equals(this.stringValue, stringValue, StringComparison.Ordinal);
        }

        public bool Equals(InvariantIntStringPair o)
        {
            if (this.stringValue == null || o.stringValue == null) return false;
            return this.value == o.value && string.Equals(this.stringValue, o.stringValue, StringComparison.Ordinal);
        }

        public int CompareTo(InvariantIntStringPair o)
        {
            if (this.stringValue == null || o.stringValue == null) return 0;
            int c = string.CompareOrdinal(this.stringValue, o.stringValue);
            if (c == 0)
            {
                if (this.value < o.value)
                {
                    return -1;
                }
                else if (this.value > o.value)
                {
                    return 1;
                }
                else
                {
                    return 0;
                }
            }
            else
            {
                return c;
            }
        }

        public int GetOriginalIndex()
        {
            return originalIndex;
        }

        public override string ToString()
        {
            return this.stringValue + "|" + this.value + "|" + this.originalIndex;
        }
    }
}

using MassTransit.Configuration;
using MassTransit.Pipeline;
using MassTransit.Topology;

namespace MyNamespace
{
    public interface IInMemoryEndpointConfiguration : IEndpointConfiguration
    {
        IInMemoryTopologyConfiguration Topology { get; }
        IEndpointConsumerConfiguration ConsumerConfiguration { get; }
        IInMemoryEndpointConfiguration CreateEndpointConfiguration(bool isChild = false);
    }

    public class InMemoryEndpointConfiguration : EndpointConfiguration, IInMemoryEndpointConfiguration
    {
        private readonly IInMemoryTopologyConfiguration _topologyConfiguration;
        private readonly IEndpointConsumerConfiguration _consumerConfiguration;

        public InMemoryEndpointConfiguration(IInMemoryTopologyConfiguration topologyConfiguration, IEndpointConsumerConfiguration consumerConfiguration)
        {
            _topologyConfiguration = topologyConfiguration;
            _consumerConfiguration = consumerConfiguration;
        }

        public InMemoryEndpointConfiguration(IInMemoryTopologyConfiguration topologyConfiguration)
            : this(topologyConfiguration, new EndpointConsumerConfiguration())
        {
        }

        public IInMemoryTopologyConfiguration Topology => _topologyConfiguration;
        public IEndpointConsumerConfiguration ConsumerConfiguration => _consumerConfiguration;

        public IInMemoryEndpointConfiguration CreateEndpointConfiguration(bool isChild = false)
        {
            IInMemoryTopologyConfiguration topologyConfiguration = isChild ? _topologyConfiguration : _topologyConfiguration.CreateTopologyConfiguration();
            return new InMemoryEndpointConfiguration(topologyConfiguration, _consumerConfiguration.CreateConfiguration());
        }
    }
}

using NCrawler;
using NCrawler.HtmlProcessor;
using NCrawler.Interfaces;
using System;
using System.Collections.Generic;
using System.Threading;

class IndexerDemo
{
    public static void Main()
    {
        // Initialize the crawler with a specified URL and configuration
        var crawler = new Crawler(new Uri("https://www.example.com"), new HtmlDocumentProcessor());

        // Configure the crawler to follow specific rules for filtering content and links
        crawler.MaximumCrawlDepth = 2;
        crawler.MaximumThreads = 5;

        // Add a custom pipeline step to process and output the filtered text content
        crawler.AddStep(new IndexingStep());

        // Run the crawler
        crawler.Run();
    }
}

public class HtmlDocumentProcessor : HtmlProcessor
{
    public override string Process(HtmlDocument htmlDoc)
    {
        // Filter out unwanted sections and links
        var unwantedSections = htmlDoc.DocumentNode.SelectNodes("//script | //style | //iframe");
        if (unwantedSections != null)
        {
            foreach (var section in unwantedSections)
            {
                section.Remove();
            }
        }

        // Extract the text content from the filtered HTML
        var textContent = htmlDoc.DocumentNode.InnerText;

        return textContent;
    }
}

public class IndexingStep : IPipelineStep
{
    public void Process(Crawler crawler, PropertyBag propertyBag)
    {
        // Get the text content from the property bag
        var textContent = propertyBag["textContent"].ToString();

        // Output the extracted text content to the console, simulating the indexing process
        Console.WriteLine(textContent);
    }
}

using System.Threading.Tasks;
using Akka.Actor;
using Akka.Dispatch;
using Akka.Dispatch.MessageQueues;

namespace Akka.Persistence
{
    internal static class InternalExtensions
    {
        /// <summary>
        /// Sends <paramref name="task"/> result to the <paramref name="receiver"/> in form of <see cref="ReplayMessagesSuccess"/>
        /// or <see cref="ReplayMessagesFailure"/> depending on the success or failure of the task.
        /// </summary>
        public static Task NotifyAboutReplayCompletion(this Task task, IActorRef receiver)
        {
            return task
                .ContinueWith(t => !t.IsFaulted ? (object) ReplayMessagesSuccess.Instance : new ReplayMessagesFailure(t.Exception))
                .PipeTo(receiver);
        }

        /// <summary>
        /// Enqueues provided <paramref name="message"/> at the beginning of the internal actor cell mailbox message queue.
        /// Requires current actor to use unbounded deque-based message queue. It will fail otherwise.
        /// </summary>
        public static void EnqueueMessageFirst(this IActorContext context, object message)
        {
            var cell = (ActorCell)context;
            var mailbox = (Mailbox<UnboundedMessageQueue, UnboundedDequeMessageQueue>)cell.Mailbox;
            var queue = (IUnboundedDequeBasedMessageQueueSemantics)mailbox.MessageQueue;
            queue.EnqueueFirst(new Envelope { Sender = context.Sender, Message = message });
        }
    }
}

using System;
