using System;
using System.Diagnostics;
using System.IO;
using NUnit.Framework;
using PRI.ProductivityExtensions.TemporalExtensions;
using PRI.Messaging.Patterns;
using PRI.Messaging.Patterns.Extensions.Bus;
using Queue.Mocks;

namespace Queue
{
    public class HandlingMessagesThenSpeedIsAcceptable
    {

        [Test, Explicit]
        public void CompareCapacity()
        {
            var message1 = new Message1 {CorrelationId = "1234"};

            var bus = new Bus();
            bus.AddHandler(new Message2Consumer());
            bus.AddTranslator(new Pipe());
            var stopwatch = Stopwatch.StartNew();
            for (var i = 0; i < 53000000; ++i)
                bus.Handle(message1);
            Console.WriteLine(stopwatch.Elapsed.ToEnglishString());

            var bus1 = new Bus();
            var directory = Path.GetDirectoryName(new Uri(GetType().Assembly.CodeBase).LocalPath);
            bus1.AddHandlersAndTranslators(directory, "Queue*.dll", GetType().Namespace);

            stopwatch = Stopwatch.StartNew();
            for (var i = 0; i < 53000000; ++i)
                bus1.Handle(message1);
            Console.WriteLine(stopwatch.Elapsed.ToEnglishString());
        }

        [Test , Explicit]
        public void MeasureCapacity()
        {
            var message1 = new Message2 {CorrelationId = "1234"};

            var bus = new Bus();
            var message2Consumer = new Message2Consumer();
            bus.AddHandler(message2Consumer);
            var stopwatch = Stopwatch.StartNew();
            var messageCount = 53000000;
            for (var i = 0; i < messageCount; ++i)
                bus.Handle(message1);
            Console.WriteLine("{0} million in {1}", messageCount/1.Million(), stopwatch.Elapsed.ToEnglishString());
            Console.WriteLine(message2Consumer.MessageReceivedCount);
            Assert.AreSame(message1, Message2Consumer.LastMessageReceived);
            Assert.AreEqual(messageCount, message2Consumer.MessageReceivedCount);

            message2Consumer = new Message2Consumer();
            stopwatch = Stopwatch.StartNew();
            for (var i = 0; i < messageCount; ++i)
                message2Consumer.Handle(message1);
            Console.WriteLine(stopwatch.Elapsed.ToEnglishString());
        }
    }
}

using osu.Game.Beatmaps;
using osu.Game.Rulesets;
using osu.Game.Rulesets.Mods;
using osu.Game.Rulesets.Objects;
using System;

public class ModPerfectTestScene : TestScene
{
    private readonly Ruleset ruleset;
    private readonly ModPerfect mod;

    public ModPerfectTestScene(Ruleset ruleset, ModPerfect mod)
    {
        this.ruleset = ruleset;
        this.mod = mod;
    }

    public void CreateHitObjectTest(HitObjectTestData testData)
    {
        var player = CreateModPlayer(testData);
        Add(player);

        if (testData.FailOnMiss)
        {
            AddStep("Check for failure on miss", () =>
            {
                if (player.HasMissed)
                {
                    CheckFailed();
                }
            });
        }
    }

    private PerfectModTestPlayer CreateModPlayer(HitObjectTestData testData)
    {
        var player = new PerfectModTestPlayer(ruleset, mod, testData.HitObject);
        return player;
    }

    private void CheckFailed()
    {
        AddAssert("Test failed", false);
    }
}

public class HitObjectTestData
{
    public HitObject HitObject { get; set; }
    public bool FailOnMiss { get; set; }
}

public class PerfectModTestPlayer : ModTestPlayer
{
    private readonly HitObject hitObject;

    public PerfectModTestPlayer(Ruleset ruleset, ModPerfect mod, HitObject hitObject)
        : base(ruleset, mod)
    {
        this.hitObject = hitObject;
    }

    public bool HasMissed { get; private set; }

    protected override void Update()
    {
        base.Update();

        if (hitObject.IsHit || hitObject.IsMiss)
        {
            if (hitObject.IsMiss)
            {
                HasMissed = true;
            }
        }
    }
}

