using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.SqlServer.Management.Smo;

public interface IDatabaseObjectScriptEngine{IEnumerable<SqlScriptObject> Script(Database database);}
public class SqlScriptObject{public string ScriptText { get; set; }public string ObjectName { get; set; }public string ObjectType { get; set; }}
public class DatabaseObjectScripter
{
    private readonly IEnumerable<IDatabaseObjectScriptEngine> _engines;
    public DatabaseObjectScripter(IEnumerable<IDatabaseObjectScriptEngine> engines=null){_engines = engines ?? GetDefaultEngines();}
    public IEnumerable<SqlScriptObject> Script(string databaseName)
    {
        Server server = new Server();Database database = server.Databases[databaseName];
        if (database == null) return Enumerable.Empty<SqlScriptObject>();
        var allScripts = new List<SqlScriptObject>();
        foreach (var engine in _engines) allScripts.AddRange(engine.Script(database));
        return allScripts;
    }
    private static IEnumerable<IDatabaseObjectScriptEngine> GetDefaultEngines()=> new List<IDatabaseObjectScriptEngine>(){new ExampleScriptEngine()};
}
public class ExampleScriptEngine : IDatabaseObjectScriptEngine
{
    public IEnumerable<SqlScriptObject> Script(Database database)=> new List<SqlScriptObject>(){new SqlScriptObject { ObjectName = "Example", ObjectType = "Type", ScriptText = "-- Script" }};
}

