public class PDEditorHelper : Editor
{
    private static Texture icon;
    private static List<PDEditorModule> modules = new List<PDEditorModule>();
    private static PDEditorModule defaultModule;
    private static PDPlayer pdPlayer;

    [InitializeOnLoadMethod]
    public static void Init()
    {
        icon = Resources.Load<Texture>("AudioModuleIcon");
        pdPlayer = FindObjectOfType<PDPlayer>();
    }

    public void OnEnable()
    {
        modules.Clear();
        foreach (PDEditorModule module in FindObjectsOfType<PDEditorModule>())
        {
            modules.Add(module);
        }
    }

    public void OnDrawGizmos()
    {
        #if UNITY_EDITOR
        foreach (PDEditorModule module in modules)
        {
            if (module != null && module.gameObject != null)
            {
                if (Selection.Contains(module.gameObject))
                {
                    Gizmos.color = Color.yellow;
                }
                else
                {
                    Gizmos.color = Color.white;
                }

                Gizmos.DrawIcon(module.transform.position, icon);
                Gizmos.DrawWireSphere(module.transform.position, module.distance);
            }
        }
