using System;
using System.Runtime.InteropServices;

namespace System.Net.Libuv.Native
{
    public static unsafe class UVBuffer
    {
        public delegate IntPtr AllocateBufferDelegate(int size);

        public static AllocateBufferDelegate AllocateUnixBuffer { get; set; } = DefaultAllocateUnixBuffer;
        public static AllocateBufferDelegate AllocateWindowsBuffer { get; set; } = DefaultAllocateWindowsBuffer;

        public static Unix DefaultUnix => new Unix(IntPtr.Zero, 0);
        public static Windows DefaultWindows => new Windows(IntPtr.Zero, 0);

        public static object Default
        {
            get
            {
                if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
                    return DefaultWindows;
                else
                    return DefaultUnix;
            }
        }

        private static IntPtr DefaultAllocateUnixBuffer(int size) => Marshal.AllocHGlobal(size);
        private static IntPtr DefaultAllocateWindowsBuffer(int size) => Marshal.AllocHGlobal(size);

        public struct Unix : IDisposable
        {
            public IntPtr Buffer { get; }
            public int Length { get; }

            public Unix(IntPtr buffer, int length)
            {
                Buffer = buffer;
                Length = length;
            }

            public void Dispose()
            {
                if (Buffer != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(Buffer);
                }
            }
        }

        public struct Windows : IDisposable
        {
            public IntPtr Buffer { get; }
            public int Length { get; }

            public Windows(IntPtr buffer, int length)
            {
                Buffer = buffer;
                Length = length;
            }

            public void Dispose()
            {
                if (Buffer != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(Buffer);
                }
            }
        }
    }
}

