using System;
using OpenRA.Network;
using OpenRA.Widgets;

public class GameTimerLogic
{
    private Widget timer;
    private LabelWidget status;
    private LabelWidget percentage;
    private int startTick;
    private bool shouldShowStatus;
    private string statusText;

    public GameTimerLogic(Widget timer, LabelWidget status, LabelWidget percentage)
    {
        this.timer = timer;
        this.status = status;
        this.percentage = percentage;
        this.startTick = 0;
        this.shouldShowStatus = false;
        this.statusText = string.Empty;
    }

    public void Tick(World world)
    {
        if (world.OrderManager.IsReplay)
        {
            var progress = world.OrderManager.ReplayProgress;
            percentage.GetText = () => $"{progress * 100:F2}%";
        }
        else
        {
            percentage.GetText = () => string.Empty;
        }

        if (world.IsPaused)
        {
            status.GetText = () => "Paused";
            shouldShowStatus = true;
        }
        else if (world.Speed != 1)
        {
            status.GetText = () => $"Speed: {world.Speed}x";
            shouldShowStatus = true;
        }
        else
        {
            status.GetText = () => string.Empty;
            shouldShowStatus = false;
        }

        if (shouldShowStatus)
        {
            statusText = status.GetText();
            status.GetText = () => statusText;
        }

        var elapsed = world.LocalTick - startTick;
        timer.GetText = () => FormatTime(elapsed);
    }

    public void Start(World world)
    {
        startTick = world.LocalTick;
    }

    private string FormatTime(int ticks)
    {
        var minutes = ticks / 60;
        var seconds = ticks % 60;
        return $"{minutes:00}:{seconds:00}";
    }
}

