using System;
using System.Text;

namespace CredentialsExample
{
    [Serializable]
    public class UsernamePasswordCredentials
    {
        private string _username;
        private byte[] _passwordBytes;

        public UsernamePasswordCredentials(string username, string password)
        {
            _username = username;
            SetPassword(password);
        }

        public string GetUsername()
        {
            return _username;
        }

        public void SetUsername(string username)
        {
            _username = username;
        }

        public string GetPassword()
        {
            if (_passwordBytes != null)
            {
                return Encoding.UTF8.GetString(_passwordBytes);
            }
            return null;
        }

        public void SetPassword(string password)
        {
            if (password != null)
            {
                _passwordBytes = Encoding.UTF8.GetBytes(password);
            }
            else
            {
                _passwordBytes = null;
            }
        }

        public override string ToString()
        {
            return $"UsernamePasswordCredentials{{username='{_username}', password='[PROTECTED]'}}";
        }
    }
}

