using System;
using System.Collections.Generic;
using System.Linq;
using System.Web.Mvc;

namespace DancingGoat.Controllers
{
    public class CoffeesController : Controller
    {
        private readonly ICoffeeRepository mCoffeeRepository;
        private readonly ICalculationService mCalculationService;

        public CoffeesController(ICoffeeRepository coffeeRepository, ICalculationService calculationService)
        {
            mCoffeeRepository = coffeeRepository;
            mCalculationService = calculationService;
        }

        public ActionResult Index()
        {
            var coffees = mCoffeeRepository.GetAllCoffees();
            var filterModel = new CoffeeFilterViewModel();
            var viewModel = new ProductListViewModel {
                Coffees = coffees.Select(c => MapToItemViewModel(c)).ToList(),
                Filter = filterModel };
            return View(viewModel);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult Filter(CoffeeFilterViewModel filterModel)
        {
            var filteredCoffees = mCoffeeRepository.GetFilteredCoffees(filterModel);
            var itemViewModels = filteredCoffees.Select(c => MapToItemViewModel(c)).ToList();
            return PartialView("_CoffeeListPartial", itemViewModels);
        }

        private ProductListItemViewModel MapToItemViewModel(Coffee coffee) => new ProductListItemViewModel {
            Name = coffee.Name,
            Description = coffee.Description,
            DisplayPrice = mCalculationService.CalculatePrice(coffee) };
    }

    public interface ICoffeeRepository {
        IEnumerable<Coffee> GetAllCoffees();
        IEnumerable<Coffee> GetFilteredCoffees(CoffeeFilterViewModel filter); }
    public interface ICalculationService { decimal CalculatePrice(Coffee coffee); }
    public class Coffee { public string Name { get; set; } public string Description { get; set; } public decimal BasePrice { get; set; } }
    public class CoffeeFilterViewModel { public string Origin { get; set; } public string RoastLevel { get; set; } }
    public class ProductListViewModel { public List<ProductListItemViewModel> Coffees { get; set; } public CoffeeFilterViewModel Filter { get; set; } }
    public class ProductListItemViewModel { public string Name { get; set; } public string Description { set; get; } public decimal DisplayPrice { get; set; } }
}

