namespace ServiceClientExample
{
    public class ServiceClient
    {
        private readonly string _baseUrl;
        private string _accessToken;
        private readonly RestClient _restClient;

        public ServiceClient(string baseUrl)
        {
            _baseUrl = baseUrl;
            _restClient = new RestClient(_baseUrl);
        }

        public string GetAuthorizationUrl(string clientId, string redirectUri, string scope)
        {
            string authorizationEndpoint = "/oauth/authorize";
            string url = $"{_baseUrl}{authorizationEndpoint}?client_id={clientId}&redirect_uri={redirectUri}&scope={scope}&response_type=code";
            return url;
        }

        public string GetAccessToken(string clientId, string clientSecret, string authorizationCode, string tokenEndpoint)
        {
            var request = new RestRequest(tokenEndpoint, Method.Post);
            request.AddParameter("client_id", clientId);
            request.AddParameter("client_secret", clientSecret);
            request.AddParameter("code", authorizationCode);
            request.AddParameter("grant_type", "authorization_code");
            request.AddParameter("redirect_uri", "your_redirect_uri"); // Replace
            var response = _restClient.Execute(request);
            if (response.IsSuccessful)
            {
                // Parse response to get access token (simplified)
                _accessToken = "sample_access_token"; // Replace with actual parsing
                return _accessToken;
            }
            return null; // Handle error properly
        }

        public string GetAccountInfo()
        {
            if (string.IsNullOrEmpty(_accessToken)) return null;
            var request = new RestRequest("/api/account", Method.Get);
            request.AddHeader("Authorization", $"Bearer {_accessToken}");
            var response = _restClient.Execute(request);
            if (response.IsSuccessful)
            {
                return response.Content; // Return account info as string (simplified)
            }
            return null; // Handle error
        }

        public bool DisableAccessToken()
        {
            _accessToken = null; // Invalidate locally. API call to revoke would be needed in real scenario
            return true;
        }
    }
}

using System;

namespace ExpenseManager.Entity
{
    public enum FrequencyType
    {
        Daily,
        Weekly,
        Monthly,
        Quarterly,
        Annually
    }

    public class TransactionServiceModel
    {
        public Guid Id { get; set; }
        public bool IsExpense { get; set; }
        public decimal Amount { get; set; }
        public DateTime Date { get; set; }
        public string Description { get; set; }
        public Guid WalletId { get; set; }
        public Guid BudgetId { get; set; }
        public Guid CurrencyId { get; set; }
        public Guid CategoryId { get; set; }
        public FrequencyType? RepetitionFrequency { get; set; }
        public DateTime? RepetitionEndDate { get; set; }
        public int RepetitionInterval { get; set; }

        public TransactionServiceModel()
        {
            Id = Guid.NewGuid();
        }

        public TransactionServiceModel(bool isExpense, decimal amount, DateTime date, string description, Guid walletId, Guid budgetId, Guid currencyId, Guid categoryId)
        {
            Id = Guid.NewGuid();
            IsExpense = isExpense;
            Amount = amount;
            Date = date;
            Description = description;
            WalletId = walletId;
            BudgetId = budgetId;
            CurrencyId = currencyId;
            CategoryId = categoryId;
        }

        public TransactionServiceModel(bool isExpense, decimal amount, DateTime date, string description, Guid walletId, Guid budgetId, Guid currencyId, Guid categoryId, FrequencyType repetitionFrequency, DateTime repetitionEndDate, int repetitionInterval)
        {
            Id = Guid.NewGuid();
            IsExpense = isExpense;
            Amount = amount;
            Date = date;
            Description = description;
            WalletId = walletId;
            BudgetId = budgetId;
            CurrencyId = currencyId;
            CategoryId = categoryId;
            RepetitionFrequency = repetitionFrequency;
            RepetitionEndDate = repetitionEndDate;
            RepetitionInterval = repetitionInterval;
        }
    }
}

