using System;
using WallNetCore.Helper;

namespace WallNetCore.Random
{
    [Serializable]
    public class ExtendedRandom : System.Random, IRandom
    {
        private const int HalfwayInt = int.MaxValue / 2;

        public ExtendedRandom() : this(BitConverter.ToInt32(Guid.NewGuid().ToByteArray(), 0)) {}

        public ExtendedRandom(int seed) : base(seed) {}

        public bool NextBool()
        {
            return Next() < HalfwayInt;
        }

        public double NextDouble(double max)
        {
            Validate.Validate.Hard.IsPositive(max, () => $"Expected {max} to be positive.");
            return WallMath.BoundedDouble(max, NextDouble() * max);
        }

        public double NextDouble(double min, double max)
        {
            Validate.Validate.Hard.IsFalse(max <= min,
                () => $"{nameof(min)} ({min}) must be greater than {nameof(max)} ({max}). Arguments reversed?");
            return InternalNextDouble(min, max);
        }

        public float NextFloat()
        {
            byte[] byteBuffer = {0, 0, 0, 0};
            NextBytes(byteBuffer);
            return (BitConverter.ToUInt32(byteBuffer, 0) >> 8) * 5.960465E-008F;
        }

        public float NextFloat(float max)
        {
            Validate.Validate.Hard.IsPositive(max, () => $"Expected {max} to be positive.");
            return WallMath.BoundedFloat(max, NextFloat() * max);
        }

        public float NextFloat(float min, float max)
        {
            Validate.Validate.Hard.IsFalse(max <= min,
                () => $"{nameof(min)} ({min}) must be greater than {nameof(max)} ({max}). Arguments reversed?");
            return InternalNextFloat(min, max);
        }

        private double InternalNextDouble(double min, double max)
        {
            return WallMath.BoundedDouble(max, NextDouble() * (max - min) + min);
        }

        private float InternalNextFloat(float min, float max)
        {
            return WallMath.BoundedFloat(max, NextFloat() * (max - min) + min);
        }
    }
}

using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;

using MSR.Data;
using MSR.Data.Entities;
using MSR.Data.Entities.DSL.Selection;
using MSR.Data.Entities.DSL.Selection.Metrics;

namespace MSR.Tools.Visualizer.Visualizations
{
    public class CommitsByDateAndAuthor : DatePeriodVisualization
    {
        private Dictionary<string,double[]> yByAuthor;

        public CommitsByDateAndAuthor()
        {
            Type = VisualizationType.LINEWITHPOINTS;
            Title = "Commits by date and author";
        }
        public override void Init(IRepository repository)
        {
            Authors = repository.Queryable<Commit>()
                .Select(x => x.Author).Distinct().OrderBy(x => x)
                .ToArray();
            base.Init(repository);
        }
        public override void Calc(IRepository repository)
        {
            base.Calc(repository);

            x = new double[dates.Count()-1];
            yByAuthor = new Dictionary<string,double[]>();
            for (int i = 0; i < Authors.Length; i++)
            {
                yByAuthor.Add(Authors[i], new double[dates.Count()-1]);
            }

            for (int i = 0; i < Authors.Length; i++)
            {
                y = yByAuthor[Authors[i]];
                DateTime prev = dates[0];
                int counter = 0;

                for (int j = 1; j < dates.Length; j++)
                {
                    if (i == 0)
                    {
                        x[counter] = (dates[j] - dates[0]).TotalDays;
                    }
                    y[counter] = repository.SelectionDSL().Commits()
                        .DateIsGreaterOrEquelThan(prev)
                        .DateIsLesserThan(dates[j])
                        .AuthorIs(Authors[i])
                        .Count();

                    prev = dates[j];
                    counter++;
                }
            }
        }
        public override void Draw(IGraphView graph)
        {
            graph.PrepairPointsForDateScale(x, dates[0]);
            graph.YAxisTitle = "Commits";
            foreach (var y in yByAuthor)
            {
                Legend = y.Key;
                this.y = y.Value;
                base.Draw(graph);
            }
        }
        [DescriptionAttribute("Author list")]
        public string[] Authors
        {
            get; set;
        }
    }
}

