namespace ModuleStore.Schema.Parser
{
    public class NestedSelectQuery
    {
        public SelectQuery SelectQuery { get; set; }

        public NestedSelectQuery(SelectQuery query)
        {
            SelectQuery = query;
        }

        public void WriteTo(SqlWriter writer)
        {
            writer.Write("(");
            writer.WriteLine();
            writer.Indent++;
            SelectQuery.WriteTo(writer);
            writer.Indent--;
            writer.WriteLine();
            writer.Write(")");
        }

        public void WriteScript(SqlWriter writer)
        {
            WriteTo(writer);
            writer.WriteLine(";");
        }

        public override string ToString()
        {
            SqlWriter writer = new SqlWriter();
            WriteTo(writer);
            return writer.ToString();
        }
    }

    public class SelectQuery
    {
        public void WriteTo(SqlWriter writer)
        {
            writer.WriteLine("SELECT * FROM TableName");
        }
    }

    public class SqlWriter
    {
        private int _indent = 0;
        private string _output = "";

        public int Indent
        {
            get { return _indent; }
            set { _indent = value; }
        }

        public void WriteLine()
        {
            _output += Environment.NewLine + new string(' ', _indent * 4);
        }

        public void WriteLine(string text)
        {
            _output += Environment.NewLine + new string(' ', _indent * 4) + text;
        }

        public void Write(string text)
        {
            _output += text;
        }

        public override string ToString()
        {
            return _output;
        }
    }
}

