        {
            var markup =
@"class A
{
void M()
{
            int i = 1;{|caret:|}
    }
}";
            var expected =
@"class A
{
    void M()
    {
        int i = 1;
    }
}";
            using var workspace = CreateTestWorkspace(markup, out var locations);
            var documentURI = locations["caret"].Single().Uri;
            var documentText = await workspace.CurrentSolution.GetDocumentFromURI(documentURI).GetTextAsync();

