using System;
using System.Runtime.InteropServices;

internal static class NativeMethods
{
    internal static class Darwin
    {
        private const int CTL_KERN = 1;
        private const int KERN_OSRELEASE = 2;
        private const int BUFFER_LENGTH = 256;

        internal static string GetKernelRelease()
        {
            int[] name = new int[] { CTL_KERN, KERN_OSRELEASE };
            byte[] buffer = new byte[BUFFER_LENGTH];
            IntPtr bufferPtr = Marshal.UnsafeAddrOfPinnedArrayElement(buffer, 0);
            ulong length = (ulong)BUFFER_LENGTH;

            int result = sysctl(name, (uint)name.Length, bufferPtr, ref length, IntPtr.Zero, 0);

            if (result != 0)
            {
                return string.Empty; // Or throw an exception: throw new PlatformNotSupportedException("Failed to get kernel release.");
            }

            return Marshal.PtrToStringAnsi(bufferPtr);
        }

        [DllImport("libc")]
        private static extern int sysctl(int[] name, uint namelen, IntPtr oldp, ref ulong oldlenp, IntPtr newp, ulong newlen);
    }
}

public static class KernelVersionHelper
{
    public static string GetDarwinKernelVersion()
    {
        if (RuntimeInformation.IsOSPlatform(OSPlatform.OSX) || RuntimeInformation.IsOSPlatform(OSPlatform.iOS) || RuntimeInformation.IsOSPlatform(OSPlatform.TvOS) || RuntimeInformation.IsOSPlatform(OSPlatform.WatchOS))
        {
            return NativeMethods.Darwin.GetKernelRelease();
        }
        return string.Empty; // Or throw PlatformNotSupportedException for non-Darwin platforms
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using System.Linq;
using System.Linq.Expressions;
using System.Reflection;

namespace SmartStore
{
    public static class LinqExtensions
    {
        public static PropertyInfo ExtractPropertyInfo(this LambdaExpression propertyAccessor)
        {
            return propertyAccessor.ExtractMemberInfo() as PropertyInfo;
        }

        public static FieldInfo ExtractFieldInfo(this LambdaExpression propertyAccessor)
        {
            return propertyAccessor.ExtractMemberInfo() as FieldInfo;
        }

        [SuppressMessage("ReSharper", "CanBeReplacedWithTryCastAndCheckForNull")]
        public static MemberInfo ExtractMemberInfo(this LambdaExpression propertyAccessor)
        {
            Guard.ArgumentNotNull(() => propertyAccessor);

            MemberInfo info;
            try
            {
                MemberExpression operand;
                // o => o.PropertyOrField
                LambdaExpression expression = propertyAccessor;

                if (expression.Body is UnaryExpression)
                {
                    // If the property is not an Object, then the member access expression will be wrapped in a conversion expression
                    // (object)o.PropertyOrField
                    UnaryExpression body = (UnaryExpression)expression.Body;
                    // o.PropertyOrField
                    operand = (MemberExpression)body.Operand;
                }
                else
                {
                    // o.PropertyOrField
                    operand = (MemberExpression)expression.Body;
                }

                // Member
                MemberInfo member = operand.Member;
                info = member;
            }
            catch (Exception e)
            {
                throw new ArgumentException("The property or field accessor expression is not in the expected format 'o => o.PropertyOrField'.", e);
            }

            return info;
        }

    }

}

