using System;
using System.IO;
using System.Windows.Forms;
using Gallio.Common.Reflection;

namespace Gallio.Icarus
{
    public partial class CodeViewer : UserControl
    {
        private TextBox textEditorControl = new TextBox();

        public class CodeLocation
        {
            public string FilePath;
            public int LineNumber;
            public int ColumnNumber;
        }

        public CodeViewer(CodeLocation location)
        {
            InitializeComponent();
            if (location != null && !string.IsNullOrEmpty(location.FilePath))
            {
                LoadFile(location.FilePath);
                if (location.LineNumber > 0)
                    JumpTo(location.LineNumber, location.ColumnNumber);
            }
        }

        private void InitializeComponent()
        {
            textEditorControl.Dock = DockStyle.Fill;
            textEditorControl.ReadOnly = true;
            textEditorControl.Multiline = true;
            textEditorControl.WordWrap = false;
            textEditorControl.Font = new System.Drawing.Font("Courier New", 10);
            textEditorControl.KeyPress += textEditorControl_KeyPress;
            Controls.Add(textEditorControl);
        }

        private void LoadFile(string filePath)
        {
            try { textEditorControl.Text = File.ReadAllText(filePath); }
            catch (FileNotFoundException) { textEditorControl.Text = "File not found: " + filePath; }
            catch (Exception ex) { textEditorControl.Text = "Error loading file: " + ex.Message; }
        }

        public void JumpTo(int lineNumber, int columnNumber)
        {
            if (lineNumber > 0)
            {
                int index = 0;
                for (int i = 1; i < lineNumber && i <= textEditorControl.Lines.Length; i++)
                    index += textEditorControl.Lines[i - 1].Length + 1;
                textEditorControl.SelectionStart = index;
                textEditorControl.ScrollToCaret();
            }
        }

        private void textEditorControl_KeyPress(object sender, KeyPressEventArgs e) { e.Handled = true; }
    }
}

