// Placeholder for XAnyEvent - assuming it's defined elsewhere or similar structure
[StructLayout(LayoutKind.Sequential)]
public struct XAnyEvent
{
    public int type;
    public ulong serial;
    public bool send_event;
    public IntPtr display;
    public IntPtr window;
}

/// <summary>
/// Represents an X PropertyEvent structure, detailing property change events.
/// </summary>
[StructLayout(LayoutKind.Sequential)]
public struct XPropertyEvent
{
    /// <summary>
    /// Common event fields, inherited from XAnyEvent.
    /// </summary>
    public XAnyEvent common__;

    /// <summary>
    /// The atom of the property that was changed.
    /// </summary>
    public Atom atom;

    /// <summary>
    /// The timestamp when the property was changed.
    /// </summary>
    public IntPtr time;

    /// <summary>
    /// The state of the property change (e.g., NewValue, Deleted).
    /// </summary>
    public int state__;

    /// <summary>
    /// Gets the event type.
    /// </summary>
    public int type => common__.type;

    /// <summary>
    /// Gets the serial number of the last request processed by the server.
    /// </summary>
    public ulong serial => common__.serial;

    /// <summary>
    /// Gets a value indicating whether the event was sent by SendEvent.
    /// </summary>
    public bool send_event => common__.send_event;

    /// <summary>
    /// Gets the display the event was reported from.
    /// </summary>
    public IntPtr display => common__.display;

    /// <summary>
    /// Gets the window which received the event.
    /// </summary>
    public IntPtr window => common__.window;

    /// <summary>
    /// Gets the state of the property change.
    /// </summary>
    public int state => state__;

    /// <inheritdoc />
    public override string ToString()
    {
        return $"XPropertyEvent {{ type={type}, serial={serial}, send_event={send_event}, display={display}, window={window}, atom={atom}, time={time}, state={state} }}";
    }
}

using System.Collections.Generic;
using System.Threading;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Options;
using Microsoft.CodeAnalysis.PooledObjects;
using Microsoft.CodeAnalysis.Structure;

namespace Microsoft.CodeAnalysis.CSharp.Structure
{
    internal class CompilationUnitStructureProvider : AbstractSyntaxNodeStructureProvider<CompilationUnitSyntax>
    {
        protected override void CollectBlockSpans(
            CompilationUnitSyntax compilationUnit,
            ArrayBuilder<BlockSpan> spans,
            OptionSet options,
            CancellationToken cancellationToken)
        {
            CSharpStructureHelpers.CollectCommentBlockSpans(compilationUnit, spans);

            // extern aliases and usings are outlined in a single region
            var externsAndUsings = new List<SyntaxNode>();
            externsAndUsings.AddRange(compilationUnit.Externs);
            externsAndUsings.AddRange(compilationUnit.Usings);
            externsAndUsings.Sort((node1, node2) => node1.SpanStart.CompareTo(node2.SpanStart));

            spans.AddIfNotNull(CSharpStructureHelpers.CreateBlockSpan(
                externsAndUsings, autoCollapse: true,
                type: BlockTypes.Imports, isCollapsible: true));

            if (compilationUnit.Usings.Count > 0 ||
                compilationUnit.Externs.Count > 0 ||
                compilationUnit.Members.Count > 0 ||
                compilationUnit.AttributeLists.Count > 0)
            {
                CSharpStructureHelpers.CollectCommentBlockSpans(compilationUnit.EndOfFileToken.LeadingTrivia, spans);
            }
        }

        protected override bool SupportedInWorkspaceKind(string kind)
        {
            return true;
        }
    }
}

namespace Xsharp.Events
{

using System;
using System.Runtime.InteropServices;
using OpenSystem.Platform;
