using UnityEngine;

public class Cheat : MonoBehaviour
{
    public enum InventoryType { Ship, Base }
    private InventoryModel model;
    private InventoryController controller;
    private InventoryType inventoryType;

    private void Start()
    {
        model = FindObjectOfType<InventoryModel>();
        controller = FindObjectOfType<InventoryController>();
    }

    private void Update()
    {
        // Example usage of AddItems method
        if (Input.GetKeyDown(KeyCode.A))
        {
            AddItems(InventoryType.Ship, 1, 10);
        }
        else if (Input.GetKeyDown(KeyCode.B))
        {
            AddItems(InventoryType.Base, 2, 20);
        }
    }

    public void AddItems(InventoryType type, int itemId, int quantity)
    {
        inventoryType = type;
        switch (inventoryType)
        {
            case InventoryType.Ship:
                AddItemToInventory(itemId, quantity, model.ShipInventory);
                break;
            case InventoryType.Base:
                AddItemToInventory(itemId, quantity, model.BaseInventory);
                break;
            default:
                Debug.LogError("Invalid inventory type");
                break;
        }
    }

    private void AddItemToInventory(int itemId, int quantity, List<int> inventory)
    {
        for (int i = 0; i < quantity; i++)
        {
            controller.AddItem(itemId, 1);
        }
    }
}

