using System;
using System.Runtime.ExceptionServices;
using System.Threading;

namespace System.Threading.Tasks
{
    internal static class ExceptionDispatchHelper
    {
        internal static void ThrowAsync(Exception exception, SynchronizationContext targetContext)
        {
            if (exception == null)
                return;

            // TODO - decide how to cleanly do it so it lights up if TA is defined
            //if (exception is ThreadAbortException)
            //    return;

            ExceptionDispatchInfo exceptionDispatchInfo = ExceptionDispatchInfo.Capture(exception);

            if (targetContext != null)
            {
                try
                {
                    targetContext.Post((edi) => ((ExceptionDispatchInfo)edi).Throw(), exceptionDispatchInfo);
                }
                catch
                {
                    // Something went wrong in the Post; let's try using the thread pool instead:
                    ThrowAsync(exception, null);
                }
                return;
            }

            bool scheduled = true;
            try
            {
                new SynchronizationContext().Post((edi) => ((ExceptionDispatchInfo)edi).Throw(), exceptionDispatchInfo);
            }
            catch
            {
                // Something went wrong when scheduling the thrower; we do our best by throwing the exception here:
                scheduled = false;
            }

            if (!scheduled)
                exceptionDispatchInfo.Throw();
        }
    }  // ExceptionDispatchHelper
}  // namespace

// ExceptionDispatchHelper.cs

using System;
using System.Collections;
using System.Data.Entity.Infrastructure;
using System.Linq;

public class AsyncDecompiledQueryable : IDbAsyncEnumerable
{
    private readonly IQueryable inner;

    public AsyncDecompiledQueryable(IQueryable inner)
    {
        this.inner = inner;
    }

    public IDbAsyncEnumerator GetAsyncEnumerator()
    {
        if (inner is IDbAsyncEnumerable asyncEnumerable)
        {
            return asyncEnumerable.GetAsyncEnumerator();
        }
        else
        {
            throw new NotSupportedException("The source queryable does not support asynchronous enumeration.");
        }
    }
}

public class AsyncDecompiledQueryable<T> : IDbAsyncEnumerable<T>
{
    private readonly IQueryable<T> inner;

    public AsyncDecompiledQueryable(IQueryable<T> inner)
    {
        this.inner = inner;
    }

    public IDbAsyncEnumerator<T> GetAsyncEnumerator()
    {
        if (inner is IDbAsyncEnumerable<T> asyncEnumerable)
        {
            return asyncEnumerable.GetAsyncEnumerator();
        }
        else
        {
            throw new NotSupportedException("The source queryable does not support asynchronous enumeration.");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Web.Mvc;
using MediatR;
using Microsoft.Practices.Unity;
using SimpleBookKeeping.Commands;
using SimpleBookKeeping.Models;
using SimpleBookKeeping.Queries;

namespace SimpleBookKeeping.Controllers
{
    [Authorize]
    public class CostController : Controller
    {
        private readonly IMediator _mediator;

        public CostController()
        {
            _mediator = MvcApp.Unity.Resolve<IMediator>();
        }

        // GET: Cost
        public ActionResult Index(Guid planId)
        {
            IList<CostModel> costModels =
                _mediator.Send(new GetCostsQuery { PlanId = planId });

            ViewBag.PlanId = planId;
            return View("Index", costModels);
        }

        public ActionResult Remove(Guid id)
        {
            _mediator.Send(new RemoveCostCommand { CostId = id });
            return new EmptyResult();
        }

        public ActionResult Create(Guid planId)
        {
            var model = _mediator.Send(new CreateCostCommand { PlanId = planId });
            return View("View", model);
        }

        public ActionResult View(Guid id)
        {
            CostModel item = _mediator.Send(new GetCostQuery { CostId = id });
            return View("View", item);
        }

        public ActionResult Save(CostModel model)
        {
            if (model.PlanId == Guid.Empty)
            {
                return RedirectToAction("Index", "Plan");
            }

            foreach (var costDetailModel in model.CostDetails)
            {
                if (costDetailModel.Value == null)
                    costDetailModel.Value = 0;
            }

            if (ModelState.IsValid)
            {
                _mediator.Send(new SaveCostCommand { Cost = model });
                return RedirectToAction("Index", new { planId = model.PlanId });
            }

            return View("View", model);
        }

    }
}

using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Windows.Forms;
using System.Diagnostics;
using System.IO;

using Kitware.VTK;

namespace ActiViz.Examples {
   public partial class Form1 : Form {
      public Form1() {
         InitializeComponent();
      }

      private void renderWindowControl1_Load(object sender, EventArgs e) {
         try {
            ReadDEM();
         }
         catch(Exception ex) {
            MessageBox.Show(ex.Message, "Exception", MessageBoxButtons.OK);
         }
      }

      private void ReadDEM() {
         // Path to vtk data must be set as an environment variable
         // VTK_DATA_ROOT = "C:\VTK\vtkdata-5.8.0"
         vtkTesting test = vtkTesting.New();
         string root = test.GetDataRoot();
         string filePath = System.IO.Path.Combine(root, @"Data\SainteHelens.dem");

         vtkDEMReader reader = vtkDEMReader.New();
         reader.SetFileName(filePath);
         reader.Update();

         vtkLookupTable lut = vtkLookupTable.New();
         lut.SetHueRange(0.6, 0);
         lut.SetSaturationRange(1.0, 0);
         lut.SetValueRange(0.5, 1.0);
         double[] range = reader.GetOutput().GetScalarRange();
         lut.SetTableRange(range[0], range[1]);

         // Visualize
         vtkImageMapToColors mapColors = vtkImageMapToColors.New();
         mapColors.SetLookupTable(lut);
         mapColors.SetInputConnection(reader.GetOutputPort());

         // Create an actor
         vtkImageActor actor = vtkImageActor.New();
         actor.SetInput(mapColors.GetOutput());
         // get a reference to the renderwindow of our renderWindowControl1
         vtkRenderWindow renderWindow = renderWindowControl1.RenderWindow;
         // renderer
         vtkRenderer renderer = renderWindow.GetRenderers().GetFirstRenderer();
         // set background color
         renderer.SetBackground(0.2, 0.3, 0.4);
         // add our actor to the renderer
         renderer.AddActor(actor);
      }
   }
}

