using System;
using System.Linq;
using System.Windows.Forms;
using nmrb;

class Graph
{
    [STAThread]
    static void Main()
    {
        // Create a new mruby state object
        State state = new State();

        // Define a C# function that can be called from Ruby
        state.DefineCliMethod("hello", (args) =>
        {
            Console.WriteLine("Hello from C#!");
            return NilValue.Instance;
        });

        // Execute a Ruby code snippet
        state.Do("puts 'Hello from Ruby!'");

        // Define a C# function that takes arguments
        state.DefineCliMethod("add", (args) =>
        {
            int a = (int)args[0].FixnumValue;
            int b = (int)args[1].FixnumValue;
            return new FixnumValue(a + b);
        });

        // Execute a Ruby code snippet that calls the C# function
        state.Do("puts add(2, 3)");

        // Access and manipulate a Ruby array
        state.Do("arr = [1, 2, 3]");
        Value arr = state.GetVariable("arr");
        Console.WriteLine(string.Join(", ", arr.ToArray().Select(x => x.FixnumValue)));

        // Access and manipulate a Ruby hash
        state.Do("hash = {a: 1, b: 2}");
        Value hash = state.GetVariable("hash");
        Console.WriteLine(string.Join(", ", hash.ToDictionary().Select(x => $"{x.Key}: {x.Value.FixnumValue}")));

        // Call a Ruby function from C#
        state.Do("def greet(name); puts 'Hello, ' + name; end");
        state.FunCall("greet", new StringValue("Alice"));

        // Handle exceptions
        try
        {
            state.Do("raise 'Error message'");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }

        // Clean up
        state.Close();
    }
}

