using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Diagnostics.HealthChecks;
using Ombi.Api.Plex;
using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public class PlexHealthCheck : IHealthCheck
{
    private readonly IServiceProvider _services;

    public PlexHealthCheck(IServiceProvider services)
    {
        _services = services;
    }

    public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, CancellationToken cancellationToken = default)
    {
        try
        {
            var settingsService = _services.GetService<ISettingsService>();
            var plexSettings = await settingsService.GetSettingsAsync<PlexSettings>();

            var tasks = new List<Task<bool>>();
            foreach (var server in plexSettings.Servers)
            {
                tasks.Add(GetStatus(server));
            }

            var results = await Task.WhenAll(tasks);

            if (results.All(result => result))
            {
                return HealthCheckResult.Healthy("All Plex servers are healthy.");
            }
            else
            {
                return HealthCheckResult.Unhealthy("One or more Plex servers are not healthy.");
            }
        }
        catch (Exception ex)
        {
            return HealthCheckResult.Unhealthy("Error checking Plex server health: " + ex.Message);
        }
    }

    private async Task<bool> GetStatus(PlexServer server)
    {
        try
        {
            var plexApi = _services.GetService<IPlexApi>();
            await plexApi.GetServerStatusAsync(server);
            return true;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error checking {server.Name}: {ex.Message}");
            return false;
        }
    }
}

