using System;
using System.Collections.Generic;
using System.Xml;

public enum XacmlVersion { Version30 }

public class ActionMatch
{
    public string MatchValue { get; }

    public ActionMatch(string value) { MatchValue = value; }
}

public class TargetMatchReadWriteCollection : List<ActionMatch> { }

public class ActionElement
{
    private readonly TargetMatchReadWriteCollection _actionMatches;

    public ActionElement(XmlReader reader, XacmlVersion version)
    {
        if (reader == null) throw new ArgumentNullException(nameof(reader));
        _actionMatches = new TargetMatchReadWriteCollection();

        if (reader.Name == "Action")
        {
            if (!reader.IsEmptyElement)
            {
                reader.ReadStartElement("Action");
                while (reader.NodeType != XmlNodeType.EndElement || reader.Name != "Action")
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name == "ActionMatch")
                    {
                        ParseActionMatch(reader, version);
                    }
                    else if (!reader.EOF)
                    {
                        reader.Read();
                    } else { break; }
                }
                if (reader.NodeType == XmlNodeType.EndElement && reader.Name == "Action")
                    reader.ReadEndElement();
            } else { reader.ReadStartElement("Action"); reader.ReadEndElement(); }
        }
    }

    public ActionElement(TargetMatchReadWriteCollection actionMatches)
    {
        _actionMatches = actionMatches ?? new TargetMatchReadWriteCollection();
    }

    public TargetMatchReadWriteCollection ActionMatches => _actionMatches;

    private void ParseActionMatch(XmlReader reader, XacmlVersion version)
    {
        if (reader.Name == "ActionMatch")
        {
            string matchValue = reader.GetAttribute("MatchValue");
            reader.ReadStartElement("ActionMatch");
            reader.ReadEndElement();
            if (matchValue != null)
                _actionMatches.Add(new ActionMatch(matchValue));
        }
    }
}

