namespace FinancialManagementApp.Settings
{
    public sealed partial class SettingsPage : Page
    {
        private SQLiteConnection conn;
        private readonly SerializationService _SerializationService;

        public SettingsPage()
        {
            InitializeComponent();
            _SerializationService = new SerializationService();
        }

        protected override void OnNavigatedTo(NavigationEventArgs e)
        {
            base.OnNavigatedTo(e);
            InitializeDatabaseConnection();
        }

        private void InitializeDatabaseConnection()
        {
            var path = Path.Combine(ApplicationData.Current.LocalFolder.Path, "financial_management.db");
            conn = new SQLiteConnection(new SQLite.Net.Platform.WinRT.SQLitePlatformWinRT(), path);
        }

        private void ResetMan_Click(object sender, RoutedEventArgs e)
        {
            conn.Execute("DELETE FROM Transactions");
            conn.Execute("DELETE FROM Accounts");
            conn.Execute("DELETE FROM Budgets");
            // Add more tables to delete as needed
        }

        private void BusyTextTextBox_TextChanged(object sender, TextChangedEventArgs e)
        {
            if (BusyTextTextBox.Text.ToLower() == "reset")
            {
                ResetMan.IsEnabled = true;
            }
            else
            {
                ResetMan.IsEnabled = false;
            }
        }

        private void BusyTextTextBox_Loaded(object sender, RoutedEventArgs e)
        {
            ResetMan.IsEnabled = false;
        }
    }
}

