using System;
using Serilog.Sinks.NLog;
using Serilog.Configuration;
using Serilog.Events;

namespace Serilog
{
    /// <summary>
    /// Adds the WriteTo.NLog() extension method to <see cref="LoggerConfiguration"/>.
    /// </summary>
    public static class LoggerConfigurationsNLogExtensions
    {
        /// <summary>
        /// Adds a sink that writes adapted log events to NLog.
        /// </summary>
        /// <param name="loggerConfiguration">The logger configuration.</param>
        /// <param name="restrictedToMinimumLevel">The minimum log event level required in order to write an event to the sink.</param>
        /// <param name="formatProvider">Supplies culture-specific formatting information, or null.</param>
        /// <returns>Logger configuration, allowing configuration to continue.</returns>
        /// <exception cref="ArgumentNullException">A required parameter is null.</exception>
        public static LoggerConfiguration NLog(
            this LoggerSinkConfiguration loggerConfiguration,
            LogEventLevel restrictedToMinimumLevel = LevelAlias.Minimum,
            IFormatProvider formatProvider = null)
        {
            if (loggerConfiguration == null)
            {
                throw new ArgumentNullException("loggerConfiguration");
            }

            return loggerConfiguration.Sink(new NLogSink(formatProvider), restrictedToMinimumLevel);
        }
    }
}

using System;
using System.IO;
using System.Xml.Serialization;

public interface IAuthenticationStorage
{
    AuthenticationData GetAuthenticationData();
    void SaveAuthenticationData(AuthenticationData data);
    void Clear();
}

public class AuthenticationStorage : IAuthenticationStorage
{
    private static readonly string authenticationStorageFolder = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "YourAppName");
    private static readonly string authenticationStorageFilePath = Path.Combine(authenticationStorageFolder, "auth.xml");

    public AuthenticationData GetAuthenticationData()
    {
        if (!File.Exists(authenticationStorageFilePath))
        {
            return null;
        }
        try
        {
            XmlSerializer serializer = new XmlSerializer(typeof(AuthenticationData));
            using (FileStream fileStream = new FileStream(authenticationStorageFilePath, FileMode.Open))
            {
                return (AuthenticationData)serializer.Deserialize(fileStream);
            }
        }
        catch
        {
            return null;
        }
    }

    public void SaveAuthenticationData(AuthenticationData data)
    {
        Directory.CreateDirectory(authenticationStorageFolder);
        XmlSerializer serializer = new XmlSerializer(typeof(AuthenticationData));
        using (TextWriter writer = new StreamWriter(authenticationStorageFilePath))
        {
            serializer.Serialize(writer, data);
        }
    }

    public void Clear()
    {
        if (File.Exists(authenticationStorageFilePath))
        {
            File.Delete(authenticationStorageFilePath);
        }
    }
}

