using System;
using System.Collections.Generic;
using System.ComponentModel.Composition;
using System.Threading.Tasks;
using LiteGuard;
using Raven.Client.Documents;
using Raven.Client.Documents.Indexes;

public class ResetIndexesCommand
{
}

[Export(typeof(ICommandHandler<ResetIndexesCommand>))]
public class ResetIndexesCommandHandler : ICommandHandler<ResetIndexesCommand>
{
    private readonly IDocumentStore _documentStore;
    private readonly IEnumerable<AbstractIndexCreationTask> _indexCreationTasks;

    [ImportingConstructor]
    public ResetIndexesCommandHandler(IDocumentStore documentStore, [ImportMany] IEnumerable<AbstractIndexCreationTask> indexCreationTasks)
    {
        Guard.AgainstNullArgument(nameof(documentStore), documentStore);
        Guard.AgainstNullArgument(nameof(indexCreationTasks), indexCreationTasks);

        _documentStore = documentStore;
        _indexCreationTasks = indexCreationTasks;
    }

    public async Task Execute(ResetIndexesCommand command)
    {
        Guard.AgainstNullArgument(nameof(command), command);

        foreach (var indexCreationTask in _indexCreationTasks)
        {
            try
            {
                await indexCreationTask.ResetIndexAsync(_documentStore);
                // Optionally log success, e.g.,
                // Console.WriteLine($"Index '{indexCreationTask.IndexName}' reset successfully.");
            }
            catch (Exception ex)
            {
                // Optionally log error, e.g.,
                // Console.WriteLine($"Error resetting index '{indexCreationTask.IndexName}': {ex.Message}");
                // Consider more robust error handling/logging in a real application
            }
        }
        // Optionally return a result object indicating overall success/failure
    }
}

public interface ICommandHandler<TCommand> where TCommand : class
{
    Task Execute(TCommand command);
}

