    public class ThreadLocalStorageLifecycleTests
    {
        private IContainer _mainContainer;
        private IContainer _nestedContainer;

        [SetUp]
        public void SetUp()
        {
            _mainContainer = new Container(c =>
            {
                c.For<Rule>().Use<ColorRule>().LifecycleIs<ThreadLocalStorageLifecycle>();
            });

            _nestedContainer = _mainContainer.GetNestedContainer();
        }

        [Test]
        public void MainContainer_InstanceRetrieval_DoesNotCache()
        {
            var instance1 = _mainContainer.GetInstance<Rule>();
            var instance2 = _mainContainer.GetInstance<Rule>();

            Assert.AreNotSame(instance1, instance2);
        }

        [Test]
        public void NestedContainer_InstanceRetrieval_DoesNotCache()
        {
            var instance1 = _nestedContainer.GetInstance<Rule>();
            var instance2 = _nestedContainer.GetInstance<Rule>();

            Assert.AreNotSame(instance1, instance2);
        }

        [Test]
