public abstract class SerializeBase
{
    public Encoding Encoder { get; set; }

    public SerializeBase(Encoding encoder)
    {
        Encoder = encoder;
    }

    public byte[] Serialize(object obj)
    {
        if (obj == null)
        {
            throw new ArgumentNullException(nameof(obj));
        }

        return SerializeInternal(obj);
    }

    protected abstract byte[] SerializeInternal(object obj);

    public object Deserialize(byte[] data, Type type)
    {
        if (data == null)
        {
            throw new ArgumentNullException(nameof(data));
        }

        if (type == null)
        {
            throw new ArgumentNullException(nameof(type));
        }

        return DeserializeInternal(data, type);
    }

    protected abstract object DeserializeInternal(byte[] data, Type type);

    public T Deserialize<T>(byte[] data)
    {
        return (T)Deserialize(data, typeof(T));
    }

    public static SerializeBase GetInstance()
    {
        // Return an instance of a concrete serializer, e.g., BinarySerialize
        // This could be implemented using a factory pattern or dependency injection
        return new BinarySerialize(Encoding.UTF8);
    }
}

// Example concrete serializer class
public class BinarySerialize : SerializeBase
{
    public BinarySerialize(Encoding encoder) : base(encoder) { }

    protected override byte[] SerializeInternal(object obj)
    {
        // Implement binary serialization logic here
        using (var stream = new MemoryStream())
        {
            var formatter = new BinaryFormatter();
            formatter.Serialize(stream, obj);
            return stream.ToArray();
        }
    }

    protected override object DeserializeInternal(byte[] data, Type type)
    {
        // Implement binary deserialization logic here
        using (var stream = new MemoryStream(data))
        {
            var formatter = new BinaryFormatter();
            return formatter.Deserialize(stream);
        }
    }
}

