namespace bsn.ModuleStore.Sql.Script {
    public sealed class NestedSelectQuery: Tuple {
        private readonly SelectQuery value;

        [Rule("<Tuple> ::= ~'(' <SelectQuery> ~')'")]
        [Rule("<ExpressionParens> ::= ~'(' <SelectQuery> ~')'")]
        public NestedSelectQuery(SelectQuery value) {
            Debug.Assert(value != null);
            this.value = value;
        }

        public SelectQuery Value {
            get {
                return value;
            }
        }

        public override void WriteTo(SqlWriter writer) {
            WriteCommentsTo(writer);
            writer.Write('(');
            using (writer.Indent()) {
                writer.WriteScript(value, WhitespacePadding.NewlineBefore);
            }
            writer.WriteLine();
            writer.Write(')');
        }
    }
}

using System;
using System.Runtime.ExceptionServices;
using System.Threading;

public class ExceptionDispatchHelper
{
    public static void ThrowAsync(Exception exception, SynchronizationContext targetContext)
    {
        if (exception == null)
        {
            throw new ArgumentNullException(nameof(exception));
        }

        var exceptionDispatchInfo = ExceptionDispatchInfo.Capture(exception);

        if (targetContext != null)
        {
            try
            {
                targetContext.Post(state => exceptionDispatchInfo.Throw(), null);
            }
            catch (Exception ex)
            {
                // Fallback mechanism: use the thread pool
                ThreadPool.QueueUserWorkItem(state => exceptionDispatchInfo.Throw());
            }
        }
        else
        {
            // Default synchronization context
            SynchronizationContext.SetSynchronizationContext(new SynchronizationContext());
            try
            {
                SynchronizationContext.Current.Post(state => exceptionDispatchInfo.Throw(), null);
            }
            catch (Exception ex)
            {
                // Fallback mechanism: use the thread pool
                ThreadPool.QueueUserWorkItem(state => exceptionDispatchInfo.Throw());
            }
        }
    }
}

