namespace MyWebApp
{
    public class Startup
    {
        public Startup(IHostingEnvironment env)
        {
            var builder = new ConfigurationBuilder()
                .SetBasePath(env.ContentRootPath)
                .AddJsonFile("appsettings.json", optional: true, reloadOnChange: true)
                .AddJsonFile($"appsettings.{env.EnvironmentName}.json", optional: true)
                .AddEnvironmentVariables();
            Configuration = builder.Build();
        }

        public IConfigurationRoot Configuration { get; }

        // This method gets called by the runtime. Use this method to add services to the container.
        public void ConfigureServices(IServiceCollection services)
        {
            // Add framework services.
            services.AddMvc();
        }

        // This method gets called by the runtime. Use this method to configure the HTTP request pipeline.
        public void Configure(IApplicationBuilder app, IHostingEnvironment env, ILoggerFactory loggerFactory)
        {
            loggerFactory.AddConsole(Configuration.GetSection("Logging"));
            loggerFactory.AddDebug();

            if (env.IsDevelopment())
            {
                app.UseDeveloperExceptionPage();
                app.UseBrowserLink();
            }
            else
            {
                app.UseExceptionHandler("/Home/Error");
            }

            app.UseStaticFiles();

            app.UseMvc(routes =>
            {
                routes.MapRoute(
                    name: "default",
                    template: "{controller=Home}/{action=Index}/{id?}");
            });
        }
    }
}

using System;
using System.Linq;
using Enigma.Reflection;

public class TypeAnalyzer
{
    public static Type[] TryGetComplexTypes(Type type)
    {
        var complexTypes = new System.Collections.Generic.List<Type>();

        if (type.Classification == TypeClassification.Complex)
        {
            complexTypes.Add(type);
        }
        else if (type.Classification == TypeClassification.Nullable)
        {
            var underlyingType = type.GetGenericTypeDefinition().GetGenericArguments().FirstOrDefault();
            if (underlyingType != null)
            {
                complexTypes.AddRange(TryGetComplexTypes(underlyingType));
            }
        }
        else if (type.Classification == TypeClassification.Dictionary)
        {
            var keyType = type.GetGenericTypeDefinition().GetGenericArguments().FirstOrDefault();
            var valueType = type.GetGenericTypeDefinition().GetGenericArguments().LastOrDefault();
            if (keyType != null && valueType != null)
            {
                complexTypes.AddRange(TryGetComplexTypes(keyType));
                complexTypes.AddRange(TryGetComplexTypes(valueType));
            }
        }
        else if (type.Classification == TypeClassification.Collection)
        {
            var elementType = type.GetGenericTypeDefinition().GetGenericArguments().FirstOrDefault();
            if (elementType != null)
            {
                complexTypes.AddRange(TryGetComplexTypes(elementType));
            }
        }

        return complexTypes.ToArray();
    }
}

public enum TypeClassification
{
    Complex,
    Nullable,
    Dictionary,
    Collection
}

public class ExtendedType
{
    public TypeClassification Classification { get; set; }
    public TypeProvider Provider { get; set; }
}

