    public sealed class IpV6MobilityOptionIpV4DefaultRouterAddress : IpV6MobilityOptionIpV4Address
    {
        public IpV6MobilityOptionIpV4DefaultRouterAddress(IpV4Address defaultRouterAddress)
            : base(IpV6MobilityOptionType.IpV4DefaultRouterAddress, defaultRouterAddress)
        {
        }

        private IpV6MobilityOptionIpV4DefaultRouterAddress() : this(IpV4Address.Zero) { }

        public IpV4Address DefaultRouterAddress => Address;

        internal static IpV6MobilityOptionIpV4DefaultRouterAddress CreateInstance(byte[] buffer, int offset, byte optionLength)
        {
            if (optionLength != 4) return null;
            IpV4Address address = new IpV4Address(buffer, offset);
            return new IpV6MobilityOptionIpV4DefaultRouterAddress(address);
        }

        internal override int GetDataLength() => IpV4Address.SizeOf;

         internal static bool TryRead(byte[] buffer, int offset, out IpV6MobilityOptionIpV4DefaultRouterAddress value, out int bytesRead)
        {
            value = null;
            bytesRead = 0;
            if (offset + 6 > buffer.Length) return false;
            if (buffer[offset] != (byte)IpV6MobilityOptionType.IpV4DefaultRouterAddress) return false;
            if (buffer[offset+1] != 4) return false;
            IpV4Address address = new IpV4Address(buffer, offset + 2);
            value = new IpV6MobilityOptionIpV4DefaultRouterAddress(address);
            bytesRead = 6;
            return true;
        }
    }
}

using System;
using System.Diagnostics.CodeAnalysis;
using FluentAssertions;
using Microsoft.UnitTests.Core.XUnit;

[SuppressMessage("ReSharper", "UnusedVariable")]
public class CountdownDisposableTest
{
    [Fact]
    public void CountdownDisposable_CallbackInvokedOnce()
    {
        int callbackCount = 0;
        Action callback = () => callbackCount++;
        var countdown = new CountdownDisposable(callback);

        countdown.Increment().Dispose();
        callbackCount.Should().Be(1);

        countdown.Increment().Dispose();
        callbackCount.Should().Be(1);
    }

    [Fact]
    public void CountdownDisposable_CallbackInvokedAfterMultipleIncrements()
    {
        int callbackCount = 0;
        Action callback = () => callbackCount++;
        var countdown = new CountdownDisposable(callback);

        var disposable1 = countdown.Increment();
        var disposable2 = countdown.Increment();
        callbackCount.Should().Be(0);

        disposable1.Dispose();
        callbackCount.Should().Be(0);
        disposable2.Dispose();
        callbackCount.Should().Be(1);
    }

    private class CountdownDisposable
    {
        private readonly Action _callback;
        private int _count;
        private bool _callbackInvoked;

        public CountdownDisposable(Action callback)
        {
            _callback = callback ?? throw new ArgumentNullException(nameof(callback));
            _count = 0;
            _callbackInvoked = false;
        }

        public IDisposable Increment()
        {
            _count++;
            return new DisposableAction(Decrement);
        }

        private void Decrement()
        {
            if (_count > 0)
            {
                _count--;
                if (_count == 0 && !_callbackInvoked)
                {
                    _callback();
                    _callbackInvoked = true;
                }
            }
        }

        private class DisposableAction : IDisposable
        {
            private readonly Action _disposeAction;
            public DisposableAction(Action disposeAction) => _disposeAction = disposeAction;
            public void Dispose() => _disposeAction?.Invoke();
        }
    }
}

