using MediatR;
using Microsoft.Practices.Unity;
using System;
using System.Web.Mvc;

namespace FinancialPlanning.Controllers
{
    public class CostController : Controller
    {
        private readonly IMediator _mediator;

        public CostController(IMediator mediator)
        {
            _mediator = mediator;
        }

        public ActionResult Index(Guid planId)
        {
            var query = new GetCostsQuery { PlanId = planId };
            var costs = _mediator.Send(query);
            return View(costs);
        }

        public ActionResult Remove(Guid id)
        {
            var command = new RemoveCostCommand { Id = id };
            _mediator.Send(command);
            return RedirectToAction("Index");
        }

        public ActionResult Create(Guid planId)
        {
            var model = new CostModel { PlanId = planId };
            return View(model);
        }

        [HttpPost]
        public ActionResult Create(CostModel model)
        {
            if (ModelState.IsValid)
            {
                var command = new CreateCostCommand { CostModel = model };
                _mediator.Send(command);
                return RedirectToAction("Index", new { planId = model.PlanId });
            }
            return View(model);
        }

        public ActionResult View(Guid id)
        {
            var query = new GetCostQuery { Id = id };
            var cost = _mediator.Send(query);
            return View(cost);
        }

        public ActionResult Save(Guid id)
        {
            var query = new GetCostQuery { Id = id };
            var cost = _mediator.Send(query);
            return View(cost);
        }

        [HttpPost]
        public ActionResult Save(CostModel model)
        {
            if (ModelState.IsValid)
            {
                var command = new SaveCostCommand { CostModel = model };
                _mediator.Send(command);
                return RedirectToAction("Index", new { planId = model.PlanId });
            }
            return View(model);
        }
    }
}

