namespace MvcOpenID.ASPX.Basic.Models
{
    /// <summary>
    /// IIdentity implementation of OpenId logins.
    /// </summary>
    public class OpenIdIdentity : IIdentity
    {
        private System.Web.Security.FormsAuthenticationTicket ticket;

        /// <summary>
        /// Constructor.
        /// </summary>
        /// <param name="ticket">Ticket to be used to construct the IIdentity.</param>
        public OpenIdIdentity(System.Web.Security.FormsAuthenticationTicket ticket)
        {
            this.ticket = ticket;
            UserInfo = UserInfo.FromString(ticket.UserData);
        }

        /// <summary>
        /// Authentication Type.
        /// </summary>
        /// <remarks>You will most likely want to rename this to reflect your project's name</remarks>
        public string AuthenticationType
        {
            get { return "MvcOpenID"; }
        }

        /// <summary>
        /// Return if the user is authenticated.
        /// </summary>
        /// <remarks>This always returns true as User.Identity in controllers only be castable to OpenIdIdentity if we actually set it in the Global.asax.cs. See the MvcApplication_PostAuthenticateRequest method.</remarks>
        public bool IsAuthenticated
        {
            get { return true; }
        }

        /// <summary>
        /// Username of the user.
        /// </summary>
        public string Name
        {
            get { return ticket.Name; }
        }

        /// <summary>
        /// User info of the user that is logged in.
        /// </summary>
        public UserInfo UserInfo
        {
            get;
            private set;
        }
    }
}

using System;
using DotVVM.Framework.Compilation.ControlTree.Resolved;

namespace DotVVM.Framework.Compilation.ControlTree
{
    /// <summary>
    /// Represents the definition of a control type within the framework.
    /// </summary>
    public sealed class ControlType : IEquatable<ControlType>
    {
        /// <summary>
        /// Gets the type of the control.
        /// </summary>
        public Type Type { get; }

        /// <summary>
        /// Gets the type of the control builder, if any.
        /// </summary>
        public Type? ControlBuilderType { get; }

        /// <summary>
        /// Gets the virtual path to the control definition.
        /// </summary>
        public string VirtualPath { get; }

        /// <summary>
        /// Gets the data context requirement for the control.
        /// </summary>
        public DataContextRequirement DataContextRequirement { get; }

        /// <summary>
        /// Initializes a new instance of the <see cref="ControlType"/> class.
        /// </summary>
        /// <param name="type">The type of the control.</param>
        /// <param name="controlBuilderType">The type of the control builder.</param>
        /// <param name="virtualPath">The virtual path to the control definition.</param>
        /// <param name="dataContextRequirement">The data context requirement.</param>
        public ControlType(Type type, Type? controlBuilderType, string virtualPath, DataContextRequirement dataContextRequirement)
        {
            Type = type ?? throw new ArgumentNullException(nameof(type));
            ControlBuilderType = controlBuilderType;
            VirtualPath = virtualPath ?? throw new ArgumentNullException(nameof(virtualPath));
            DataContextRequirement = dataContextRequirement;
        }

        /// <inheritdoc />
        public override bool Equals(object? obj)
        {
            return Equals(obj as ControlType);
        }

        /// <inheritdoc />
        public bool Equals(ControlType? other)
        {
            if (other is null)
            {
                return false;
            }

            return Type == other.Type && ControlBuilderType == other.ControlBuilderType;
        }

        /// <inheritdoc />
        public override int GetHashCode()
        {
            return HashCode.Combine(Type, ControlBuilderType);
        }
    }
}

