/// An arc ball camera.
/// </summary>
public class ArcBallCamera : PerspectiveCamera
{
    /// <summary>
    /// The arc ball.
    /// </summary>
    private ArcBall arcBall = new ArcBall();

    /// <summary>
    /// Constructor of ArcBallCamera.
    /// </summary>
    public ArcBallCamera() {}

    /// <summary>
    /// Updates the projection matrix.
    /// </summary>
    /// <param name="gl">The OpenGL instance.</param>
    public override void TransformProjectionMatrix(OpenGL gl)
    {
        // Update projection matrix with arcball rotation
        int[] viewport = new int[4];
        gl.GetInteger(OpenGL.GL_VIEWPORT, viewport);
        arcBall.SetBounds(viewport[2], viewport[3]);
        gl.MatrixMode(OpenGL.GL_PROJECTION);
        gl.LoadIdentity();
        Perspective(gl);
        gl.MatrixMode(OpenGL.GL_MODELVIEW);
        gl.LoadIdentity();
        LookAt(gl);
        gl.MultMatrixf(arcBall.TransformMatrix.to_array());
    }

    /// <summary>
    /// Sets up a perspective projection.
    /// </summary>
    /// <param name="gl">The OpenGL instance.</param>
    protected void Perspective(OpenGL gl)
    {
        gl.Perspective(45.0f, (double)ViewportWidth / (double)ViewportHeight, 0.1f, 100.0f);
    }

    /// <summary>
    /// Positions and orients the camera to look at the origin.
    /// </summary>
    /// <param name="gl">The OpenGL instance.</param>
    protected void LookAt(OpenGL gl)
    {
        gl.LookAt(Position.X, Position.Y, Position.Z, 0, 0, 0, UpDirection.X, UpDirection.Y, UpDirection.Z);
    }
}

