using System;
using System.Collections.Generic;
using System.Linq;

public class NotificationProcessor
{
    public class BotConfig { public Dictionary<string, string> UserMappings = new Dictionary<string, string>(); }
    public class TextConfig { public string ReleaseCreatedTemplate = "Release '{ReleaseName}' in '{ProjectName}' created by '{CreatorName}'. Status: {Status}. View here: {ReleaseUrl}"; }
    public class EventRule { public string TfsCollectionUrl; public string EventType; public bool IsMatch(string collectionUrl, string eventType) => TfsCollectionUrl == collectionUrl && EventType == eventType; }
    public delegate string TextTransformation(string text);

    public static (List<string>, EventRule) ProcessReleaseCreatedEvent(
        dynamic releaseEvent,
        BotConfig botConfig,
        TextConfig textConfig,
        TextTransformation textTransform,
        List<EventRule> eventRules)
    {
        var formattedMessages = new List<string>();
        EventRule matchingRule = null;

        var projectName = releaseEvent.ProjectName;
        var releaseName = releaseEvent.ReleaseName;
        var status = releaseEvent.Status;
        var releaseUrl = releaseEvent.ReleaseUrl;
        var creatorId = releaseEvent.CreatorId;
        var creatorName = botConfig.UserMappings.ContainsKey(creatorId) ? botConfig.UserMappings[creatorId] : creatorId;

        string message = string.Format(textConfig.ReleaseCreatedTemplate,
            new
            {
                ProjectName = textTransform?.Invoke(projectName) ?? projectName,
                ReleaseName = textTransform?.Invoke(releaseName) ?? releaseName,
                Status = textTransform?.Invoke(status) ?? status,
                ReleaseUrl = textTransform?.Invoke(releaseUrl) ?? releaseUrl,
                CreatorName = textTransform?.Invoke(creatorName) ?? creatorName
            });
        formattedMessages.Add(message);

        matchingRule = eventRules.FirstOrDefault(rule => rule.IsMatch(releaseEvent.TfsCollectionUrl, "ReleaseCreated"));

        return (formattedMessages, matchingRule);
    }
}

using System;
