namespace WebLinkComponent
{
    public class WebLinkSet
    {
        private readonly IPortalViewEntity _viewEntity;
        private readonly IEnumerable<WebLink> _webLinks;

        public WebLinkSet(Entity entity, IPortalViewEntity viewEntity, IEnumerable<WebLink> webLinks)
        {
            if (viewEntity == null)
            {
                throw new ArgumentNullException(nameof(viewEntity));
            }

            _viewEntity = viewEntity;
            _webLinks = webLinks ?? Enumerable.Empty<WebLink>();

            DisplayName = GetAttribute("DisplayName") as string;
            Name = GetAttribute("Name") as string;
            Title = GetAttribute("Title") as string;
            Copy = GetAttribute("Copy") as string;
            Url = null; // Link set itself might not have a direct URL
        }

        public string DisplayName { get; }

        public string Name { get; }

        public string Title { get; }

        public string Copy { get; }

        public IEnumerable<WebLink> WebLinks => _webLinks;

        public IPortalViewEntity ViewEntity => _viewEntity;

        public bool IsEditable => _viewEntity.IsEditable;

        public string Url { get; }

        private object GetAttribute(string attributeName)
        {
            return _viewEntity.GetAttributeValue(attributeName);
        }
    }

    public interface IPortalViewEntity
    {
        object GetAttributeValue(string attributeName);
        bool IsEditable { get; }
    }

    public class WebLink
    {
        public string Title { get; set; }
        public string Url { get; set; }
        // Add other relevant properties for WebLink if needed
    }
}

namespace NCDK.FaulonSignatures
{
    using System;

    /// <summary>
    /// Represents an immutable pair of a string and an integer value,
    /// along with an original index.
    /// </summary>
    public readonly struct InvariantIntStringPair : IEquatable<InvariantIntStringPair>, IComparable<InvariantIntStringPair>
    {
        /// <summary>
        /// Gets the string value of the pair.
        /// </summary>
        public string StringValue { get; }

        /// <summary>
        /// Gets the integer value of the pair.
        /// </summary>
        public int Value { get; }

        /// <summary>
        /// Gets the original index associated with this pair.
        /// </summary>
        public int OriginalIndex { get; }

        /// <summary>
        /// Initializes a new instance of the <see cref="InvariantIntStringPair"/> struct.
        /// </summary>
        /// <param name="stringValue">The string value.</param>
        /// <param name="value">The integer value.</param>
        /// <param name="originalIndex">The original index.</param>
        public InvariantIntStringPair(string stringValue, int value, int originalIndex)
        {
            StringValue = stringValue ?? throw new ArgumentNullException(nameof(stringValue));
            Value = value;
            OriginalIndex = originalIndex;
        }

        /// <inheritdoc />
        public bool Equals(InvariantIntStringPair other)
        {
            return string.Equals(StringValue, other.StringValue, StringComparison.Ordinal) && Value == other.Value;
        }

        /// <inheritdoc />
        public override bool Equals(object obj)
        {
            return obj is InvariantIntStringPair other && Equals(other);
        }

        /// <inheritdoc />
        public override int GetHashCode()
        {
            return HashCode.Combine(StringValue.GetHashCode(StringComparison.Ordinal), Value);
        }

        /// <inheritdoc />
        public int CompareTo(InvariantIntStringPair other)
        {
            int stringComparison = string.CompareOrdinal(StringValue, other.StringValue);
            if (stringComparison != 0)
            {
                return stringComparison;
            }
            return Value.CompareTo(other.Value);
        }

        /// <inheritdoc />
        public override string ToString()
        {
            return $"{StringValue}, {Value}, Index: {OriginalIndex}";
        }
    }
}

