public static class FullNodeTestExtensions
{
    public static IWalletManager WalletManager(this IFullNode fullNode)
    {
        return fullNode.NodeService<IWalletManager>();
    }

    public static IWalletTransactionHandler WalletTransactionHandler(this IFullNode fullNode)
    {
        return fullNode.NodeService<IWalletTransactionHandler>();
    }

    public static IConsensusManager ConsensusManager(this IFullNode fullNode)
    {
        return fullNode.NodeService<IConsensusManager>();
    }

    public static ICoinView CoinView(this IFullNode fullNode)
    {
        return fullNode.NodeService<ICoinView>();
    }

    public static MempoolManager MempoolManager(this IFullNode fullNode)
    {
        return fullNode.NodeService<MempoolManager>();
    }

    public static IBlockStore BlockStore(this IFullNode fullNode)
    {
        return fullNode.NodeService<IBlockStore>();
    }

    public static IChainState GetBlockStoreTip(this IFullNode fullNode)
    {
        return fullNode.NodeService<IChainState>();
    }

    public static BitcoinAddress GetUnusedAddress(this IFullNode fullNode)
    {
        var walletManager = fullNode.WalletManager();
        var wallet = walletManager.GetWallets().FirstOrDefault();
        if (wallet == null)
            return null;

        var account = wallet.GetAccounts().FirstOrDefault();
        if (account == null)
            return null;

        var address = account.GetUnusedAddress();
        return address.Address;
    }
}

