using System;
using System.Data.Services.Client;
using System.Linq;
using Microsoft.Azure.Cosmos.Table;

public static class TableServiceExtensionMethods
{
    public static CloudTableQuery<TElement> AsTableServiceQuery<TElement>(this IQueryable<TElement> query)
        where TElement : ITableEntity, new()
    {
        // Convert the input query into a CloudTableQuery
        var cloudQuery = query as CloudTableQuery<TElement>;

        if (cloudQuery == null)
        {
            // If the query is not already a CloudTableQuery, create a new one
            cloudQuery = new CloudTableQuery<TElement>(query);
        }

        // Return the CloudTableQuery
        return cloudQuery;
    }
}

// Example usage:
public class TableEntity : ITableEntity
{
    public string PartitionKey { get; set; }
    public string RowKey { get; set; }
    public DateTime Timestamp { get; set; }
    public string ETag { get; set; }
}

class Timer
{
    static void Main()
    {
        // Create a TableClient
        var tableClient = new TableClient("DefaultEndpointsProtocol=https;AccountName=<account_name>;AccountKey=<account_key>;BlobEndpoint=<blob_endpoint>");

        // Create a query
        var query = tableClient.Query<TableEntity>();

        // Convert the query to a CloudTableQuery
        var cloudQuery = query.AsTableServiceQuery();

        // Execute the query
        var results = cloudQuery.ExecuteQuery();

        // Process the results
        foreach (var result in results)
        {
            Console.WriteLine($"PartitionKey: {result.PartitionKey}, RowKey: {result.RowKey}");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using Orchard.ContentManagement.Drivers;
using Orchard.SEO.Models;
using Orchard.UI.Resources;
using Orchard.ContentManagement;

namespace Orchard.SEO.Drivers
{
    public class MetaDriver : ContentPartDriver<MetaPart>
    {
        private readonly IWorkContextAccessor _wca;

        public MetaDriver(IWorkContextAccessor workContextAccessor)
        {
            _wca = workContextAccessor;
        }

        protected override string Prefix
        {
            get
            {
                return "meta";
            }
        }

        protected override DriverResult Display(MetaPart part, string displayType, dynamic shapeHelper)
        {
            if (displayType != "Detail") return null;
            var resourceManager = _wca.GetContext().Resolve<IResourceManager>();
            if (!String.IsNullOrWhiteSpace(part.Description))
            {
                resourceManager.SetMeta(new MetaEntry
                {
                    Name = "description",
                    Content = part.Description
                });
            }
            if (!String.IsNullOrWhiteSpace(part.Keywords))
            {
                resourceManager.SetMeta(new MetaEntry
                {
                    Name = "keywords",
                    Content = part.Keywords
                });
            }
            return null;
        }

        //GET
        protected override DriverResult Editor(MetaPart part, dynamic shapeHelper)
        {

            return ContentShape("Parts_Meta_Edit",
                () => shapeHelper.EditorTemplate(
                    TemplateName: "Parts/Meta",
                    Model: part,
                    Prefix: Prefix));
        }
        //POST
        protected override DriverResult Editor(MetaPart part, IUpdateModel updater, dynamic shapeHelper)
        {
            updater.TryUpdateModel(part, Prefix, null, null);
            return Editor(part, shapeHelper);
        }
    }
}

extern alias InteractiveHost;

using System;
using System.Diagnostics;
using System.Globalization;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis.CSharp.Scripting.Hosting;
using Xunit;

namespace Microsoft.CodeAnalysis.UnitTests.Interactive
{
    using InteractiveHost::Microsoft.CodeAnalysis.Interactive;

    public sealed class StressTests
    {
        [Fact]
        public async Task TestKill()
        {
            for (int sleep = 0; sleep < 20; sleep++)
            {
                await TestKillAfterAsync(sleep).ConfigureAwait(false);
            }
        }

        private async Task TestKillAfterAsync(int milliseconds)
        {
            using var host = new InteractiveHost(typeof(CSharpReplServiceProvider), ".", millisecondsTimeout: 1, joinOutputWritingThreadsOnDisposal: true);
            var options = InteractiveHostOptions.CreateFromDirectory(TestUtils.HostRootPath, initializationFileName: null, CultureInfo.InvariantCulture, InteractiveHostPlatform.Desktop64);

            host.InteractiveHostProcessCreated += new Action<Process>(proc =>
            {
                _ = Task.Run(async () =>
                {
                    await Task.Delay(milliseconds).ConfigureAwait(false);

                    try
                    {
                        proc.Kill();
                    }
                    catch
                    {
                    }
                });
            });

            await host.ResetAsync(options).ConfigureAwait(false);

            for (int j = 0; j < 10; j++)
            {
                await host.ExecuteAsync("1+1").ConfigureAwait(false);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Asp2017.Server.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Http.Features;
using Microsoft.AspNetCore.NodeServices;
using Microsoft.AspNetCore.SpaServices.Prerendering;
using Microsoft.Extensions.DependencyInjection;

namespace Asp2017.Server.Helpers {
    public static class HttpRequestExtensions {
        public static IRequest AbstractRequestInfo(this HttpRequest request) => new IRequest()
        {
            cookies = request.Cookies,
            headers = request.Headers,
            host = request.Host
        };

        public static async Task<RenderToStringResult> BuildPrerender(this HttpRequest request) =>
            // Prerender / Serialize application (with Universal)
            await Prerenderer.RenderToString(
                "/",
                request.HttpContext.RequestServices.GetRequiredService<INodeServices>(),
                new System.Threading.CancellationTokenSource().Token,
                new JavaScriptModuleExport(request.HttpContext.RequestServices.GetRequiredService<IHostingEnvironment>().ContentRootPath + "/ClientApp/dist/main-server"),
                $"{request.Scheme}://{request.Host}{request.HttpContext.Features.Get<IHttpRequestFeature>().RawTarget}",
                request.HttpContext.Features.Get<IHttpRequestFeature>().RawTarget,
                // ** TransferData concept **
                // Here we can pass any Custom Data we want !
                // By default we're passing down Cookies, Headers, Host from the Request object here
                new TransferData
                {
                    request = request.AbstractRequestInfo(),
                    thisCameFromDotNET = "Hi Angular it's asp.net :)"
                }, // Our simplified Request object & any other CustommData you want to send!
                30000,
                request.PathBase.ToString()
            );
    }
}

using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using SolidEdgeFramework;
using SolidEdgePart;
using SolidEdgeFrameworkSupport;

class Graph
{
    static void Main(string[] args)
    {
        try
        {
            // Connect to a running instance of Solid Edge
            Type solidEdgeType = Type.GetTypeFromProgID("SolidEdge.Application");
            SolidEdgeFramework.Application solidEdge = (SolidEdgeFramework.Application)Marshal.GetActiveObject("SolidEdge.Application");

            // Register the message filter to handle COM events
            OleMessageFilter.Register();

            // Create a new part document
            SolidEdgePart.PartDocument partDocument = (SolidEdgePart.PartDocument)solidEdge.Documents.Add(SolidEdgeFramework.SolidEdgeDocumentType IgPartDocument);

            // Add a profile set to the document
            SolidEdgePart.ProfileSet profileSet = partDocument.ProfileSets.Add();

            // Add a profile to the profile set
            SolidEdgePart.Profile profile = profileSet.Profiles.Add();

            // Add a 2D circle to the profile
            SolidEdgeFrameworkSupport.Circles2d circles2d = (SolidEdgeFrameworkSupport.Circles2d)profile.Curves2d;
            SolidEdgeFrameworkSupport.Circle2d circle2d = (SolidEdgeFrameworkSupport.Circle2d)circles2d.Add(0, 0, 10);

            // Retrieve the center point of the created circle
            object[] centerPoint = circle2d.GetCenterPoint();

            // Display the center point of the circle
            Console.WriteLine("Center Point: (" + centerPoint[0] + ", " + centerPoint[1] + ")");

            // Unregister the message filter
            OleMessageFilter.Unregister();
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }
}

using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Roslyn.Test.Utilities;
using Xunit;
using Microsoft.VisualStudio.LanguageServer.Protocol;
using LSP = Microsoft.VisualStudio.LanguageServer.Protocol;

namespace FormatDocumentTests
{
    public class FormatDocumentTests
    {
        [Fact]
        public async Task TestFormatDocumentAsync()
        {
            // Create test workspace with markup
            var workspace = new AdhocWorkspace();
            var document = workspace.AddDocument("Test", "csharp", "1.0", markup);

            // Identify caret location
            var caretPosition = new Position(0, 5);

            // Retrieve document text
            var documentText = await document.GetTextAsync();

            // Run formatting operation
            var formattedText = await RunFormatDocumentAsync(workspace, document, caretPosition);

            // Compare with expected output
            Assert.Equal(expected, formattedText);
        }

        private async Task<string> RunFormatDocumentAsync(AdhocWorkspace workspace, Document document, Position caretPosition)
        {
            // Create document formatting params
            var params_ = CreateDocumentFormattingParams(document, caretPosition);

            // Apply formatting
            var edits = await workspace.LanguageServices.GetFormattingService(document).GetEditsAsync(params_);

            // Apply text edits to original document text
            var documentText = await document.GetTextAsync();
            var formattedText = documentText.ApplyEdits(edits);

            return formattedText;
        }

        private LSP.DocumentFormattingParams CreateDocumentFormattingParams(Document document, Position caretPosition)
        {
            // TODO: Respect formatting options
            var options = new LSP.FormattingOptions();
            return new LSP.DocumentFormattingParams
            {
                TextDocument = new LSP.TextDocumentIdentifier(document.Id),
                Options = options,
                Range = new LSP.Range(caretPosition, caretPosition)
            };
        }

        private const string markup = @"
using System;

class TestClass
{
    public void TestMethod()
    {
        Console.WriteLine(""Hello World"");
    }
}
";

        private const string expected = @"
using System;

class TestClass
{
    public void TestMethod()
    {
        Console.WriteLine(""Hello World"");
    }
}
";
    }
}

