using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using InTheHand.Net.Bluetooth;

namespace NXTLib
{
    public class Utils
    {
        // Converts Bluetooth address byte array to string
        public static string AddressByte2String(byte[] address, bool separators)
        {
            if (address == null || address.Length != 6) return "";
            Array.Reverse(address); // Reverse byte order for BT address
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < address.Length; i++)
            {
                sb.Append(address[i].ToString("X2"));
                if (separators && i < address.Length - 1) sb.Append(":");
            }
            return sb.ToString();
        }

        // Converts Bluetooth address string to byte array
        public static byte[] AddressString2Byte(string address)
        {
            if (string.IsNullOrEmpty(address)) return new byte[6];
            string cleanAddress = address.Replace(":", "");
            if (cleanAddress.Length != 12) return new byte[6];

            byte[] addressBytes = new byte[6];
            for (int i = 0; i < 6; i++)
            {
                addressBytes[i] = byte.Parse(cleanAddress.Substring(i * 2, 2), System.Globalization.NumberStyles.HexNumber);
            }
            Array.Reverse(addressBytes);
            return addressBytes;
        }

        // Combines two lists of Brick objects
        public static List<Brick> Combine(List<Brick> list1, List<Brick> list2)
        {
            if (list1 == null && list2 == null) return new List<Brick>();
            if (list1 == null) return new List<Brick>(list2);
            if (list2 == null) return new List<Brick>(list1);

            List<Brick> combinedList = new List<Brick>(list1);
            combinedList.AddRange(list2);
            return combinedList;
        }
    }

    public static class StringExtensions
    {
        // Safely parses string to long, returns 0 if failed
        public static long GetValue(this string s)
        {
            if (long.TryParse(s, out long value)) return value;
            return 0;
        }
    }

    // Placeholder Brick class
    public class Brick { }
}

using ImageMagick;
using Xunit;

public class DefinesTest
{
    [Fact]
    public void TestSetGetDefines()
    {
        // Test setting and getting string define without format
        var settings1 = new MagickSettings();
        settings1.SetDefine("my-define-string", "string-value");
        Assert.Equal("string-value", settings1.GetDefine("my-define-string"));

        // Test setting and getting boolean define without format
        var settings2 = new MagickSettings();
        settings2.SetDefine("my-define-bool", true);
        Assert.Equal("True", settings2.GetDefine("my-define-bool"));

        // Test setting and getting integer define without format
        var settings3 = new MagickSettings();
        settings3.SetDefine("my-define-int", 123);
        Assert.Equal("123", settings3.GetDefine("my-define-int"));

        // Test setting and getting string define with format
        var settings4 = new MagickSettings();
        settings4.SetDefine(MagickFormat.Jpeg, "jpeg-define-string", "jpeg-string-value");
        Assert.Equal("jpeg-string-value", settings4.GetDefine(MagickFormat.Jpeg, "jpeg-define-string"));

        // Test setting and getting boolean define with format
        var settings5 = new MagickSettings();
        settings5.SetDefine(MagickFormat.Png, "png-define-bool", false);
        Assert.Equal("False", settings5.GetDefine(MagickFormat.Png, "png-define-bool"));

        // Test setting and getting integer define with format
        var settings6 = new MagickSettings();
        settings6.SetDefine(MagickFormat.Tiff, "tiff-define-int", 456);
        Assert.Equal("456", settings6.GetDefine(MagickFormat.Tiff, "tiff-define-int"));

         // Test getting non-existent define without format, should return null
        var settings7 = new MagickSettings();
        Assert.Null(settings7.GetDefine("non-existent-define"));

        // Test getting non-existent define with format, should return null
        var settings8 = new MagickSettings();
        Assert.Null(settings8.GetDefine(MagickFormat.Bmp, "non-existent-define-format"));
    }
}

using Google.Solutions.IapDesktop.Extensions.Activity.Logs;
using System.Diagnostics;

namespace Google.Solutions.IapDesktop.Extensions.Activity.Events.System
{
    public class InstanceManagerHaltForRestartEvent : SystemEventBase, IInstanceStateChangeEvent
    {
        public const string Method = "compute.instances.instanceManagerHaltForRestart";

        public override string Message => "Instance terminated by Instance Manager in order to restart the instance";

        internal InstanceManagerHaltForRestartEvent(LogRecord logRecord) : base(logRecord)
        {
            Debug.Assert(IsInstanceManagerHaltForRestartEvent(logRecord));
        }

        public static bool IsInstanceManagerHaltForRestartEvent(LogRecord record)
        {
            return record.IsSystemEvent &&
                record.ProtoPayload.MethodName == Method;
        }

        //---------------------------------------------------------------------
        // IInstanceStateChangeEvent.
        //---------------------------------------------------------------------

        public bool IsStartingInstance => false;

        public bool IsTerminatingInstance => true;
    }
}
